/* DAWAH X — ahmad, অধ্যায় 12 · খণ্ড 12 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][12]=[[2201,2201,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى مَنْ نَامَ سَاجِدًا وُضُوءٌ حَتَّى يَضْطَجِعَ فَإِنَّهُ إِذَا اضْطَجَعَ اسْتَرْخَتْ مَفَاصِلُهُ ‏","","",""],[2202,2202,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا أَخَذَ امْرَأَةً ‏ ‏أَوْ سَبَاهَا ‏ ‏فَنَازَعَتْهُ قَائِمَ سَيْفِهِ فَقَتَلَهَا فَمَرَّ عَلَيْهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُخْبِرَ بِأَمْرِهَا ‏ ‏فَنَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[2203,2203,"","","‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَى ‏ ‏مُؤْتَةَ ‏ ‏فَاسْتَعْمَلَ ‏ ‏زَيْدًا ‏ ‏فَإِنْ قُتِلَ ‏ ‏زَيْدٌ ‏ ‏فَجَعْفَرٌ ‏ ‏فَإِنْ قُتِلَ ‏ ‏جَعْفَرٌ ‏ ‏فَابْنُ رَوَاحَةَ ‏ ‏فَتَخَلَّفَ ‏ ‏ابْنُ رَوَاحَةَ ‏ ‏فَجَمَّعَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَآهُ فَقَالَ مَا خَلَّفَكَ قَالَ أُجَمِّعُ مَعَكَ قَالَ ‏ ‏لَغَدْوَةٌ ‏ ‏أَوْ ‏ ‏رَوْحَةٌ ‏ ‏خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[2204,2204,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ ‏ ‏وَطِئَ ‏ ‏حُبْلَى ‏","","",""],[2205,2205,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُصِيبَ يَوْمِ ‏ ‏الْخَنْدَقِ ‏ ‏رَجُلٌ مِنْ الْمُشْرِكِينَ وَطَلَبُوا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُجِنُّوهُ ‏ ‏فَقَالَ لَا وَلَا ‏ ‏كَرَامَةَ ‏ ‏لَكُمْ قَالُوا فَإِنَّا نَجْعَلُ لَكَ عَلَى ذَلِكَ ‏ ‏جُعْلًا ‏ ‏قَالَ وَذَلِكَ أَخْبَثُ وَأَخْبَثُ ‏","","",""],[2206,2206,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏ ‏يَتَّقِي بِفُضُولِهِ حَرَّ الْأَرْضِ وَبَرْدَهَا ‏","","",""],[2207,2207,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَالَ أَلَمْ أَنْهَكَ ‏ ‏فَانْتَهَرَهُ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏أَبُو جَهْلٍ ‏ ‏لِمَ ‏ ‏تَنْتَهِرُنِي ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏فَوَاللَّهِ لَقَدْ عَلِمْتَ مَا بِهَا رَجُلٌ أَكْثَرُ ‏ ‏نَادِيًا ‏ ‏مِنِّي قَالَ فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ { ‏فَلْيَدْعُ ‏ ‏نَادِيَهُ ‏ } ‏قَالَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَاللَّهِ لَوْ دَعَا ‏ ‏نَادِيَهُ ‏ ‏لَأَخَذَتْهُ ‏ ‏زَبَانِيَةُ ‏ ‏الْعَذَابِ ‏","","",""],[2208,2208,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏قَالَ ثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مُحَمَّدٍ الْمُحَارِبِيُّ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَخْطُبُ يَوْمَ الْجُمُعَةِ قَائِمًا ثُمَّ يَقْعُدُ ثُمَّ يَقُومُ فَيَخْطُبُ ‏","","",""],[2209,2209,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنْكُمْ مِنْ أَحَدٍ إِلَّا وَقَدْ وُكِّلَ بِهِ قَرِينُهُ مِنْ الشَّيَاطِينِ قَالُوا وَأَنْتَ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ فَأَسْلَمَ ‏","","",""],[2210,2210,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِنَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏الْجَنَّةَ فَسَمِعَ مِنْ جَانِبِهَا ‏ ‏وَجْسًا ‏ ‏قَالَ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذَا قَالَ هَذَا ‏ ‏بِلَالٌ ‏ ‏الْمُؤَذِّنُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ جَاءَ إِلَى النَّاسِ قَدْ أَفْلَحَ ‏ ‏بِلَالٌ ‏ ‏رَأَيْتُ لَهُ كَذَا وَكَذَا قَالَ فَلَقِيَهُ ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَحَّبَ بِهِ وَقَالَ مَرْحَبًا بِالنَّبِيِّ الْأُمِّيِّ قَالَ فَقَالَ وَهُوَ رَجُلٌ ‏ ‏آدَمُ ‏ ‏طَوِيلٌ ‏ ‏سَبْطٌ ‏ ‏شَعَرُهُ مَعَ أُذُنَيْهِ ‏ ‏أَوْ فَوْقَهُمَا ‏ ‏فَقَالَ مَنْ هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ فَمَضَى فَلَقِيَهُ ‏ ‏عِيسَى ‏ ‏فَرَحَّبَ بِهِ وَقَالَ مَنْ هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا ‏ ‏عِيسَى ‏ ‏قَالَ فَمَضَى فَلَقِيَهُ شَيْخٌ جَلِيلٌ مَهِيبٌ فَرَحَّبَ بِهِ وَسَلَّمَ عَلَيْهِ وَكُلُّهُمْ يُسَلِّمُ عَلَيْهِ قَالَ مَنْ هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا أَبُوكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ فَنَظَرَ فِي النَّارِ فَإِذَا قَوْمٌ يَأْكُلُونَ ‏ ‏الْجِيَفَ ‏ ‏فَقَالَ مَنْ هَؤُلَاءِ يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَؤُلَاءِ الَّذِينَ يَأْكُلُونَ لُحُومَ النَّاسِ وَرَأَى رَجُلًا أَحْمَرَ أَزْرَقَ ‏ ‏جَعْدًا ‏ ‏شَعِثًا ‏ ‏إِذَا رَأَيْتَهُ قَالَ مَنْ هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا ‏ ‏عَاقِرُ ‏ ‏النَّاقَةِ قَالَ فَلَمَّا دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسْجِدَ الْأَقْصَى ‏ ‏قَامَ ‏ ‏يُصَلِّي فَالْتَفَتَ ثُمَّ الْتَفَتَ فَإِذَا النَّبِيُّونَ أَجْمَعُونَ يُصَلُّونَ مَعَهُ فَلَمَّا انْصَرَفَ جِيءَ ‏ ‏بِقَدَحَيْنِ ‏ ‏أَحَدُهُمَا عَنْ الْيَمِينِ وَالْآخَرُ عَنْ الشِّمَالِ فِي أَحَدِهِمَا لَبَنٌ وَفِي الْآخَرِ عَسَلٌ فَأَخَذَ اللَّبَنَ فَشَرِبَ مِنْهُ فَقَالَ الَّذِي كَانَ مَعَهُ ‏ ‏الْقَدَحُ ‏ ‏أَصَبْتَ ‏ ‏الْفِطْرَةَ ‏","","",""],[2211,2211,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏مِنْهُ ‏ ‏قَالَ ثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُمْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ عَنْ شِمَالِهِ ‏ ‏فَأَقَامَنِي عَنْ يَمِينِهِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سُمَيْعٍ الزَّيَّاتِ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[2212,2212,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَنَا ‏ ‏فَرَطُكُمْ ‏ ‏عَلَى الْحَوْضِ فَمَنْ ‏ ‏وَرَدَ ‏ ‏أَفْلَحَ ‏ ‏وَيُؤْتَى بِأَقْوَامٍ فَيُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ فَأَقُولُ أَيْ رَبِّ فَيُقَالُ مَا زَالُوا بَعْدَكَ يَرْتَدُّونَ عَلَى ‏ ‏أَعْقَابِهِمْ ‏","","",""],[2213,2213,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَفَاءَلُ وَلَا ‏ ‏يَتَطَيَّرُ ‏ ‏وَيُعْجِبُهُ ‏ ‏الِاسْمُ الْحَسَنُ ‏","","",""],[2214,2214,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنَّا مَنْ لَمْ ‏ ‏يُوَقِّرْ ‏ ‏الْكَبِيرَ وَيَرْحَمْ الصَّغِيرَ وَيَأْمُرْ بِالْمَعْرُوفِ ‏ ‏وَيَنْهَى عَنْ الْمُنْكَرِ ‏","","",""],[2215,2215,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ كُلُّهُنَّ ‏ ‏فَاسِقَةٌ ‏ ‏يَقْتُلُهُنَّ الْمُحْرِمُ وَيُقْتَلْنَ فِي ‏ ‏الْحَرَمِ ‏ ‏الْفَأْرَةُ وَالْعَقْرَبُ وَالْحَيَّةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْغُرَابُ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ خَمْسٌ كُلُّهُنَّ ‏ ‏فَاسِقَةٌ ‏ ‏يَقْتُلُهُنَّ الْمُحْرِمُ وَيُقْتَلْنَ فِي ‏ ‏الْحَرَمِ ‏ ‏مِثْلَهُ ‏","","",""],[2216,2216,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا سَنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا إِلَّا وَقَدْ عَلِمْتُهُ غَيْرَ ثَلَاثٍ لَا ‏ ‏أَدْرِي ‏ ‏كَانَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ ‏ ‏أَمْ لَا وَلَا أَدْرِي كَيْفَ كَانَ يَقْرَأُ ‏ { ‏وَقَدْ بَلَغْتُ مِنْ الْكِبَرِ ‏ ‏عُتِيًّا ‏ } ‏أَوْ ‏ ‏عُسُيًّا ‏ ‏قَالَ ‏ ‏حُصَيْنٌ ‏ ‏وَنَسِيتُ الثَّالِثَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَمِعْتُهَا ‏ ‏كُلَّهَا أَنَا مِنْ ‏ ‏عُثْمَانَ بْنِ مُحَمَّدٍ ‏ { ‏عُتِيًّا ‏}","","",""],[2217,2217,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ أَهْلُ ‏ ‏مَكَّةَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَجْعَلَ لَهُمْ ‏ ‏الصَّفَا ‏ ‏ذَهَبًا وَأَنْ يُنَحِّيَ الْجِبَالَ عَنْهُمْ فَيَزْدَرِعُوا فَقِيلَ لَهُ إِنْ شِئْتَ أَنْ تَسْتَأْنِيَ بِهِمْ وَإِنْ شِئْتَ أَنْ تُؤْتِيَهُمْ الَّذِي سَأَلُوا فَإِنْ كَفَرُوا أُهْلِكُوا كَمَا أَهْلَكْتُ مَنْ قَبْلَهُمْ قَالَ ‏ ‏لَا بَلْ ‏ ‏أَسْتَأْنِي بِهِمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةَ ‏ { ‏وَمَا مَنَعَنَا أَنْ نُرْسِلَ بِالْآيَاتِ إِلَّا أَنْ كَذَّبَ بِهَا الْأَوَّلُونَ وَآتَيْنَا ‏ ‏ثَمُودَ ‏ ‏النَّاقَةَ مُبْصِرَةً ‏}","","",""],[2218,2218,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ اسْمُ ‏ ‏جُوَيْرِيَةَ ‏ ‏بَرَّةَ ‏ ‏فَكَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَرِهَ ذَلِكَ فَسَمَّاهَا ‏ ‏جُوَيْرِيَةَ ‏ ‏كَرَاهَةَ أَنْ يُقَالَ خَرَجَ مِنْ عِنْدِ ‏ ‏بَرَّةَ ‏ ‏قَالَ وَخَرَجَ بَعْدَ مَا صَلَّى فَجَاءَهَا فَقَالَتْ مَا زِلْتُ بَعْدَكَ يَا رَسُولَ اللَّهِ ‏ ‏دَائِبَةً ‏ ‏قَالَ فَقَالَ لَهَا لَقَدْ قُلْتُ بَعْدَكِ كَلِمَاتٍ لَوْ وُزِنَّ لَرَجَحْنَ بِمَا قُلْتِ ‏ ‏سُبْحَانَ اللَّهِ عَدَدَ مَا خَلَقَ اللَّهُ سُبْحَانَ اللَّهِ رِضَاءَ نَفْسِهِ سُبْحَانَ اللَّهِ زِنَةَ عَرْشِهِ سُبْحَانَ اللَّهِ مِدَادَ كَلِمَاتِهِ ‏","","",""],[2219,2219,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏حَالَ ‏ ‏دُونَهُ ‏ ‏غَيَايَةٌ ‏ ‏فَأَكْمِلُوا ‏ ‏الْعِدَّةَ ‏ ‏وَالشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏ ‏يَعْنِي أَنَّهُ نَاقِصٌ ‏","","",""],[2220,2220,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ ‏ ‏أَفَأَقْضِيهِ عَنْهَا فَقَالَ لَوْ كَانَ عَلَى أُمِّكَ دَيْنٌ أَكُنْتَ قَاضِيَهُ عَنْهَا قَالَ نَعَمْ قَالَ فَدَيْنُ اللَّهِ أَحَقُّ أَنْ ‏ ‏يُقْضَى ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏فَقَالَ ‏ ‏الْحَكَمُ ‏ ‏وَسَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏وَنَحْنُ جَمِيعًا جُلُوسٌ حِينَ ‏ ‏حَدَّثَ ‏ ‏مُسْلِمٌ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏قَالَا سَمِعْنَا ‏ ‏مُجَاهِدًا ‏ ‏يَذْكُرُ هَذَا ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏","","",""],[2221,2221,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏أَجْرَهُ وَاسْتَعَطَ ‏","","",""],[2222,2222,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏وُهَيْبٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الذَّبْحِ وَالرَّمْيِ وَالْحَلْقِ وَالتَّقْدِيمِ وَالتَّأْخِيرِ فَقَالَ لَا ‏ ‏حَرَجَ ‏","","",""],[2223,2223,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِكَتِفٍ مَشْوِيَّةٍ فَأَكَلَ مِنْهَا ‏ ‏نُتَفًا ‏ ‏ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ مِنْ ذَلِكَ ‏","","",""],[2224,2224,"","","‏ ‏حَدَّثَنِي ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الصِّحَّةَ ‏ ‏وَالْفَرَاغَ ‏ ‏نِعْمَتَانِ مِنْ نِعَمِ اللَّهِ ‏ ‏مَغْبُونٌ ‏ ‏فِيهِمَا كَثِيرٌ مِنْ النَّاسِ ‏","","",""],[2225,2225,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏أَنَّهُ حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ مِنْ كَتِفٍ ‏ ‏أَوْ ذِرَاعٍ ‏ ‏ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2226,2226,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ ثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُعَلِّمُهُمْ هَذَا الدُّعَاءَ كَمَا يُعَلِّمُهُمْ السُّورَةَ مِنْ الْقُرْآنِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ شَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ غَيْرَ أَنَّهُ قَالَ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[2227,2227,"","","‏ ‏قَالَ ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَدْعُو عِنْدَ ‏ ‏الْكَرْبِ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ أَنْتَ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا أَنْتَ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ الرِّيَاحِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبِّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏يَعْنِي مِثْلَ دُعَاءِ الْكَرْبِ ‏","","",""],[2228,2228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏زَائِدَةَ بْنِ أَبِي الرُّقَادِ ‏ ‏عَنْ ‏ ‏زِيَادٍ النُّمَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ رَجَبٌ قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي رَجَبٍ وَشَعْبَانَ وَبَارِكْ لَنَا فِي رَمَضَانَ وَكَانَ يَقُولُ لَيْلَةُ الْجُمُعَةِ غَرَّاءُ وَيَوْمُهَا ‏ ‏أَزْهَرُ ‏","","",""],[2229,2229,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ الرِّيَاحِيِّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَمِّ نَبِيِّكُمْ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ لَيْلَةَ أُسْرِيَ بِي ‏ ‏مُوسَى بْنَ عِمْرَانَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏رَجُلًا ‏ ‏آدَمَ ‏ ‏طُوَالًا ‏ ‏جَعْدَ ‏ ‏الرَّأْسِ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏وَرَأَيْتُ ‏ ‏عِيسَى ابْنَ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَرْبُوعَ ‏ ‏الْخَلْقِ فِي الْحُمْرَةِ وَالْبَيَاضِ ‏ ‏سَبْطًا ‏","","",""],[2230,2230,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِأَصْحَابِهِ ‏ ‏اجْعَلُوهَا عُمْرَةً فَإِنِّي لَوْ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا ‏ ‏اسْتَدْبَرْتُ ‏ ‏لَأَمَرْتُكُمْ بِهَا وَيَحِلُّ مَنْ لَيْسَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏وَكَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَدْيٌ ‏","","",""],[2231,2231,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَتْ الْعُمْرَةُ فِي الْحَجِّ إِلَى يَوْمِ الْقِيَامَةِ وَخَلَّلَ بَيْنَ أَصَابِعِهِ ‏","","",""],[2232,2232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَعَرَّسَ ‏ ‏مِنْ اللَّيْلِ فَرَقَدَ وَلَمْ يَسْتَيْقِظْ إِلَّا بِالشَّمْسِ قَالَ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ فَصَلَّى رَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏مَا تَسُرُّنِي الدُّنْيَا وَمَا فِيهَا بِهَا ‏ ‏يَعْنِي الرُّخْصَةَ ‏","","",""],[2233,2233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏يُرِيدُ ‏ ‏مَكَّةَ ‏ ‏فَصَامَ حَتَّى أَتَى ‏ ‏عُسْفَانَ ‏ ‏قَالَ ‏ ‏فَدَعَا بِإِنَاءٍ فَوَضَعَهُ عَلَى يَدِهِ حَتَّى نَظَرَ النَّاسُ إِلَيْهِ ثُمَّ أَفْطَرَ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏مَنْ شَاءَ صَامَ وَمَنْ شَاءَ أَفْطَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏فَذَكَرَهُ بِإِسْنَادِهِ أَوْ مَعْنَاهُ ‏","","",""],[2234,2234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏قَابُوسُ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقْبَلَ إِلَيْهِمْ مُسْرِعًا قَالَ حَتَّى أَفْزَعَنَا مِنْ سُرْعَتِهِ فَلَمَّا انْتَهَى إِلَيْنَا قَالَ ‏ ‏جِئْتُ مُسْرِعًا أُخْبِرُكُمْ بِلَيْلَةِ الْقَدْرِ فَأُنْسِيتُهَا بَيْنِي وَبَيْنَكُمْ وَلَكِنْ الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ ‏","","",""],[2235,2235,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏إِنَّ هَذَا الْبَلَدَ حَرَامٌ حَرَّمَهُ اللَّهُ يَوْمَ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ فَهُوَ حَرَامٌ حَرَّمَهُ اللَّهُ إِلَى يَوْمِ الْقِيَامَةِ مَا أُحِلَّ لِأَحَدٍ فِيهِ الْقَتْلُ غَيْرِي وَلَا يَحِلُّ لِأَحَدٍ بَعْدِي فِيهِ حَتَّى تَقُومَ السَّاعَةُ وَمَا أُحِلَّ لِي فِيهِ إِلَّا سَاعَةٌ مِنْ النَّهَارِ فَهُوَ حَرَامٌ حَرَّمَهُ اللَّهُ عَزَّ وَجَلَّ إِلَى أَنْ تَقُومَ السَّاعَةُ وَلَا ‏ ‏يُعْضَدُ ‏ ‏شَوْكُهُ وَلَا ‏ ‏يُخْتَلَى ‏ ‏خَلَاهُ ‏ ‏وَلَا يُنَفَّرُ صَيْدُهُ وَلَا ‏ ‏تُلْتَقَطُ ‏ ‏لُقَطَتُهُ ‏ ‏إِلَّا ‏ ‏لِمُعَرِّفٍ ‏ ‏قَالَ فَقَالَ ‏ ‏الْعَبَّاسُ ‏ ‏وَكَانَ مِنْ أَهْلِ الْبَلَدِ ‏ ‏قَدْ عَلِمَ الَّذِي لَا بُدَّ لَهُمْ مِنْهُ إِلَّا ‏ ‏الْإِذْخِرَ ‏ ‏يَا رَسُولَ اللَّهِ فَإِنَّهُ لَا بُدَّ لَهُمْ مِنْهُ فَإِنَّهُ لِلْقُبُورِ وَالْبُيُوتِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا ‏ ‏الْإِذْخِرَ ‏","","",""],[2236,2236,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏وَاقِدٌ أَبُو عَبْدِ اللَّهِ الْخَيَّاطُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏سَمْنٌ ‏ ‏وَأَقِطٌ ‏ ‏وَضَبٌّ فَأَكَلَ السَّمْنَ ‏ ‏وَالْأَقِطَ ‏ ‏ثُمَّ قَالَ ‏ ‏لِلضَّبِّ إِنَّ هَذَا الشَّيْءَ مَا أَكَلْتُهُ قَطُّ فَمَنْ شَاءَ أَنْ يَأْكُلَهُ فَلْيَأْكُلْهُ قَالَ فَأَكَلَ عَلَى خِوَانِهِ ‏","","",""],[2237,2237,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ فِي رَأْسِهِ مِنْ صُدَاعٍ كَانَ بِهِ ‏ ‏أَوْ شَيْءٍ كَانَ بِهِ بِمَاءٍ يُقَالُ ‏ ‏لَحْيُ جَمَلٍ ‏","","",""],[2238,2238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُودَى ‏ ‏الْمُكَاتَبُ ‏ ‏بِقَدْرِ مَا أَدَّى دِيَةَ الْحُرِّ وَبِقَدْرِ مَا رَقَّ دِيَةَ الْعَبْدِ ‏","","",""],[2239,2239,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا اجْتَمَعَ الْقَوْمُ لِغَسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَيْسَ فِي الْبَيْتِ إِلَّا أَهْلُهُ عَمُّهُ ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏وَعَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَالْفَضْلُ بْنُ الْعَبَّاسِ ‏ ‏وَقُثَمُ بْنُ الْعَبَّاسِ ‏ ‏وَأُسَامَةُ بْنُ زَيْدِ بْنِ حَارِثَةَ ‏ ‏وَصَالِحٌ ‏ ‏مَوْلَاهُ فَلَمَّا اجْتَمَعُوا لِغَسْلِهِ نَادَى مِنْ وَرَاءِ الْبَابِ ‏ ‏أَوْسُ بْنُ خَوْلِيِّ الْأَنْصَارِيُّ ‏ ‏ثُمَّ أَحَدُ ‏ ‏بَنِي عَوْفِ بْنِ الْخَزْرَجِ ‏ ‏وَكَانَ بَدْرِيًّا ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ لَهُ يَا ‏ ‏عَلِيُّ ‏ ‏نَشَدْتُكَ ‏ ‏اللَّهَ وَحَظَّنَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏ادْخُلْ فَدَخَلَ فَحَضَرَ غَسْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَلِ مِنْ غَسْلِهِ شَيْئًا قَالَ فَأَسْنَدَهُ إِلَى صَدْرِهِ وَعَلَيْهِ قَمِيصُهُ وَكَانَ ‏ ‏الْعَبَّاسُ ‏ ‏وَالْفَضْلُ ‏ ‏وَقُثَمُ ‏ ‏يُقَلِّبُونَهُ مَعَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَكَانَ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَصَالِحٌ ‏ ‏مَوْلَاهُمَا يَصُبَّانِ الْمَاءَ وَجَعَلَ ‏ ‏عَلِيٌّ ‏ ‏يَغْسِلُهُ وَلَمْ يُرَ مِنْ رَسُولِ اللَّهِ شَيْءٌ مِمَّا يُرَى مِنْ الْمَيِّتِ وَهُوَ يَقُولُ بِأَبِي وَأُمِّي مَا أَطْيَبَكَ حَيًّا وَمَيِّتًا حَتَّى إِذَا فَرَغُوا مِنْ غَسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ يُغَسَّلُ بِالْمَاءِ وَالسِّدْرِ جَفَّفُوهُ ثُمَّ صُنِعَ بِهِ مَا يُصْنَعُ بِالْمَيِّتِ ثُمَّ ‏ ‏أُدْرِجَ ‏ ‏فِي ثَلَاثَةِ أَثْوَابٍ ثَوْبَيْنِ أَبْيَضَيْنِ وَبُرْدِ ‏ ‏حِبَرَةٍ ‏ ‏ثُمَّ دَعَا ‏ ‏الْعَبَّاسُ ‏ ‏رَجُلَيْنِ فَقَالَ لِيَذْهَبْ أَحَدُكُمَا إِلَى ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏وَكَانَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏يَضْرَحُ لِأَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَلْيَذْهَبْ الْآخَرُ إِلَى ‏ ‏أَبِي طَلْحَةَ بْنِ سَهْلٍ الْأَنْصَارِيِّ ‏ ‏وَكَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَلْحَدُ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ثُمَّ قَالَ ‏ ‏الْعَبَّاسُ ‏ ‏لَهُمَا حِينَ سَرَّحَهُمَا اللَّهُمَّ ‏ ‏خِرْ ‏ ‏لِرَسُولِكَ قَالَ فَذَهَبَا فَلَمْ يَجِدْ صَاحِبُ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏أَبَا عُبَيْدَةَ ‏ ‏وَوَجَدَ صَاحِبُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَبَا طَلْحَةَ ‏ ‏فَجَاءَ بِهِ ‏ ‏فَلَحَدَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2240,2240,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏خُصَيْفُ بْنُ عَبْدِ الرَّحْمَنِ الْجَزَرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏يَا ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏عَجَبًا لِاخْتِلَافِ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏إِهْلَالِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَوْجَبَ فَقَالَ إِنِّي لَأَعْلَمُ النَّاسِ بِذَلِكَ إِنَّهَا إِنَّمَا كَانَتْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّةً وَاحِدَةً فَمِنْ هُنَالِكَ اخْتَلَفُوا ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجًّا فَلَمَّا صَلَّى فِي مَسْجِدِهِ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْهِ ‏ ‏أَوْجَبَ ‏ ‏فِي مَجْلِسِهِ ‏ ‏فَأَهَلَّ ‏ ‏بِالْحَجِّ حِينَ فَرَغَ مِنْ رَكْعَتَيْهِ فَسَمِعَ ذَلِكَ مِنْهُ أَقْوَامٌ فَحَفِظُوا عَنْهُ ثُمَّ رَكِبَ فَلَمَّا اسْتَقَلَّتْ بِهِ نَاقَتُهُ أَهَلَّ وَأَدْرَكَ ذَلِكَ مِنْهُ أَقْوَامٌ وَذَلِكَ أَنَّ النَّاسَ إِنَّمَا كَانُوا يَأْتُونَ ‏ ‏أَرْسَالًا ‏ ‏فَسَمِعُوهُ حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ ‏ ‏يُهِلُّ ‏ ‏فَقَالُوا إِنَّمَا أَهَلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ ثُمَّ مَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا عَلَا عَلَى شَرَفِ ‏ ‏الْبَيْدَاءِ ‏ ‏أَهَلَّ وَأَدْرَكَ ذَلِكَ مِنْهُ أَقْوَامٌ فَقَالُوا إِنَّمَا أَهَلَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ عَلَا عَلَى شَرَفِ ‏ ‏الْبَيْدَاءِ ‏ ‏وَايْمُ اللَّهِ لَقَدْ أَوْجَبَ فِي مُصَلَّاهُ ‏ ‏وَأَهَلَّ ‏ ‏حِينَ اسْتَقَلَّتْ بِهِ نَاقَتُهُ ‏ ‏وَأَهَلَّ ‏ ‏حِينَ عَلَا عَلَى شَرَفِ ‏ ‏الْبَيْدَاءِ ‏ ‏فَمَنْ أَخَذَ بِقَوْلِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَهَلَّ فِي مُصَلَّاهُ إِذَا فَرَغَ مِنْ رَكْعَتَيْهِ ‏","","",""],[2241,2241,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ مِائَةَ بَدَنَةٍ نَحَرَ مِنْهَا ثَلَاثِينَ بَدَنَةً بِيَدِهِ ثُمَّ أَمَرَ ‏ ‏عَلِيًّا ‏ ‏فَنَحَرَ مَا بَقِيَ مِنْهَا وَقَالَ ‏ ‏اقْسِمْ لُحُومَهَا وَجِلَالَهَا وَجُلُودَهَا بَيْنَ النَّاسِ وَلَا تُعْطِيَنَّ جَزَّارًا مِنْهَا شَيْئًا وَخُذْ لَنَا مِنْ كُلِّ بَعِيرٍ ‏ ‏حُذْيَةً مِنْ لَحْمٍ ثُمَّ اجْعَلْهَا فِي قِدْرٍ وَاحِدَةٍ حَتَّى نَأْكُلَ مِنْ لَحْمِهَا وَنَحْسُوَ مِنْ مَرَقِهَا فَفَعَلَ ‏","","",""],[2242,2242,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ يَا ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏أَرَأَيْتَ قَوْلَكَ مَا حَجَّ رَجُلٌ لَمْ يَسُقْ ‏ ‏الْهَدْيَ ‏ ‏مَعَهُ ثُمَّ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏إِلَّا ‏ ‏حَلَّ ‏ ‏بِعُمْرَةٍ وَمَا طَافَ بِهَا حَاجٌّ قَدْ سَاقَ مَعَهُ ‏ ‏الْهَدْيَ ‏ ‏إِلَّا اجْتَمَعَتْ لَهُ عُمْرَةٌ وَحَجَّةٌ وَالنَّاسُ لَا يَقُولُونَ هَذَا فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ وَمَنْ مَعَهُ مِنْ أَصْحَابِهِ لَا يَذْكُرُونَ إِلَّا الْحَجَّ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏الْهَدْيُ ‏ ‏أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏وَيُحِلَّ بِعُمْرَةٍ فَجَعَلَ الرَّجُلُ مِنْهُمْ يَقُولُ يَا رَسُولَ اللَّهِ إِنَّمَا هُوَ الْحَجُّ فَيَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَيْسَ بِالْحَجِّ وَلَكِنَّهَا عُمْرَةٌ ‏","","",""],[2243,2243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا أَعْمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِشَةَ ‏ ‏لَيْلَةَ ‏ ‏الْحَصْبَةِ ‏ ‏إِلَّا قَطْعًا لِأَمْرِ أَهْلِ الشِّرْكِ فَإِنَّهُمْ كَانُوا يَقُولُونَ إِذَا ‏ ‏بَرَأَ ‏ ‏الدَّبَرْ ‏ ‏وَعَفَا ‏ ‏الْأَثَرْ ‏ ‏وَدَخَلَ ‏ ‏صَفَرْ ‏ ‏فَقَدْ حَلَّتْ الْعُمْرَةُ لِمَنْ ‏ ‏اعْتَمَرْ ‏","","",""],[2244,2244,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ جَبْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كَانَ ‏ ‏أَهْدَى جَمَلَ ‏ ‏أَبِي جَهْلٍ ‏ ‏الَّذِي كَانَ اسْتَلَبَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فِي رَأْسِهِ بُرَةٌ مِنْ فِضَّةٍ عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏فِي هَدْيِهِ ‏ ‏وَقَالَ ‏ ‏فِي مَوْضِعٍ آخَرَ لِيَغِيظَ بِذَلِكَ الْمُشْرِكِينَ ‏","","",""],[2245,2245,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي حَارِثَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فِي رَمَضَانَ ‏ ‏فَصَامَ وَصَامَ الْمُسْلِمُونَ مَعَهُ حَتَّى إِذَا كَانَ ‏ ‏بِالْكَدِيدِ ‏ ‏دَعَا بِمَاءٍ فِي ‏ ‏قَعْبٍ ‏ ‏وَهُوَ عَلَى رَاحِلَتِهِ فَشَرِبَ وَالنَّاسُ يَنْظُرُونَ يُعْلِمُهُمْ أَنَّهُ قَدْ أَفْطَرَ فَأَفْطَرَ الْمُسْلِمُونَ ‏","","",""],[2246,2246,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏يَسْدِلُونَ ‏ ‏أَشْعَارَهُمْ وَكَانَ الْمُشْرِكُونَ يَفْرُقُونَ رُءُوسَهُمْ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ مُوَافَقَةُ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏فِي بَعْضِ مَا لَمْ يُؤْمَرْ بِهِ فِيهِ ‏ ‏فَسَدَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاصِيَتَهُ ثُمَّ فَرَقَ بَعْدُ ‏","","",""],[2247,2247,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْفَضْلِ بْنِ عَبَّاسِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَيِّمُ ‏ ‏أَوْلَى بِأَمْرِهَا وَالْيَتِيمَةُ تُسْتَأْمَرُ فِي نَفْسِهَا وَإِذْنُهَا صُمَاتُهَا ‏","","",""],[2248,2248,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَدَّ ابْنَتَهُ ‏ ‏زَيْنَبَ ‏ ‏عَلَى ‏ ‏أَبِي الْعَاصِ بْنِ الرَّبِيعِ ‏ ‏وَكَانَ إِسْلَامُهَا قَبْلَ إِسْلَامِهِ بِسِتِّ سِنِينَ عَلَى النِّكَاحِ الْأَوَّلِ وَلَمْ يُحْدِثْ شَهَادَةً وَلَا صَدَاقًا ‏","","",""],[2249,2249,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏طَلْحَةُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَجُلٌ امْرَأَةً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏بَلْعَجْلَانَ ‏ ‏فَدَخَلَ بِهَا فَبَاتَ عِنْدَهَا فَلَمَّا أَصْبَحَ قَالَ مَا وَجَدْتُهَا عَذْرَاءَ قَالَ فَرُفِعَ شَأْنُهُمَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏الْجَارِيَةَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهَا فَقَالَتْ بَلَى قَدْ كُنْتُ عَذْرَاءَ قَالَ ‏ ‏فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَلَاعَنَا ‏ ‏وَأَعْطَاهَا الْمَهْرَ ‏","","",""],[2250,2250,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ بْنِ يَزِيدَ بْنِ رُكَانَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ إِبْرَاهِيمَ الشَّيْبَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجْمِ الْيَهُودِيِّ وَالْيَهُودِيَّةِ عِنْدَ بَابِ ‏ ‏مَسْجِدِهِ ‏ ‏فَلَمَّا وَجَدَ الْيَهُودِيُّ مَسَّ الْحِجَارَةِ قَامَ عَلَى صَاحِبَتِهِ فَحَنَى عَلَيْهَا يَقِيهَا مَسَّ الْحِجَارَةِ حَتَّى قُتِلَا جَمِيعًا ‏ ‏فَكَانَ مِمَّا صَنَعَ اللَّهُ عَزَّ وَجَلَّ لِرَسُولِهِ فِي ‏ ‏تَحْقِيقِ الزِّنَا مِنْهُمَا ‏","","",""],[2251,2251,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِشَاةٍ مَيْتَةٍ فَقَالَ هَلَّا اسْتَمْتَعْتُمْ ‏ ‏بِإِهَابِهَا ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهَا مَيْتَةٌ فَقَالَ إِنَّمَا حَرُمَ أَكْلُهَا ‏","","",""],[2252,2252,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏مُحَمَّدِ بْنِ مُسْلِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ إِلَى ‏ ‏قَيْصَرَ ‏ ‏يَدْعُوهُ إِلَى الْإِسْلَامِ وَبَعَثَ كِتَابَهُ مَعَ ‏ ‏دِحْيَةَ الْكَلْبِيِّ ‏ ‏وَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَدْفَعَهُ إِلَى عَظِيمِ ‏ ‏بُصْرَى ‏ ‏لِيَدْفَعَهُ إِلَى ‏ ‏قَيْصَرَ ‏ ‏فَدَفَعَهُ عَظِيمُ ‏ ‏بُصْرَى ‏ ‏وَكَانَ ‏ ‏قَيْصَرُ ‏ ‏لَمَّا كَشَفَ اللَّهُ عَزَّ وَجَلَّ عَنْهُ جُنُودَ ‏ ‏فَارِسَ ‏ ‏مَشَى مِنْ ‏ ‏حِمْصَ ‏ ‏إِلَى ‏ ‏إِيلْيَاءَ ‏ ‏عَلَى ‏ ‏الزَّرَابِيِّ ‏ ‏تُبْسَطُ لَهُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏فَلَمَّا جَاءَ ‏ ‏قَيْصَرَ ‏ ‏كِتَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ حِينَ قَرَأَهُ الْتَمِسُوا لِي مِنْ قَوْمِهِ مَنْ أَسْأَلُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَخْبَرَنِي ‏ ‏أَبُو سُفْيَانَ بْنُ حَرْبٍ ‏ ‏أَنَّهُ كَانَ ‏ ‏بِالشَّامِ ‏ ‏فِي رِجَالٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَدِمُوا تُجَّارًا وَذَلِكَ فِي الْمُدَّةِ الَّتِي كَانَتْ بَيْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ كُفَّارِ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَأَتَانِي رَسُولُ ‏ ‏قَيْصَرَ ‏ ‏فَانْطَلَقَ بِي وَبِأَصْحَابِي حَتَّى قَدِمْنَا ‏ ‏إِيلْيَاءَ ‏ ‏فَأُدْخِلْنَا عَلَيْهِ فَإِذَا هُوَ جَالِسٌ فِي مَجْلِسِ مُلْكِهِ عَلَيْهِ التَّاجُ وَإِذَا حَوْلَهُ عُظَمَاءُ ‏ ‏الرُّومِ ‏ ‏فَقَالَ لِتَرْجُمَانِهِ سَلْهُمْ أَيُّهُمْ أَقْرَبُ نَسَبًا بِهَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏أَنَا أَقْرَبُهُمْ إِلَيْهِ نَسَبًا قَالَ مَا قَرَابَتُكَ مِنْهُ قَالَ قُلْتُ هُوَ ابْنُ عَمِّي قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏وَلَيْسَ فِي الرَّكْبِ يَوْمَئِذٍ رَجُلٌ مِنْ ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏غَيْرِي قَالَ فَقَالَ ‏ ‏قَيْصَرُ ‏ ‏أَدْنُوهُ مِنِّي ثُمَّ أَمَرَ بِأَصْحَابِي فَجُعِلُوا خَلْفَ ظَهْرِي عِنْدَ كَتِفِي ثُمَّ قَالَ لِتَرْجُمَانِهِ قُلْ لِأَصْحَابِهِ إِنِّي سَائِلٌ هَذَا عَنْ الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ فَإِنْ كَذَبَ فَكَذِّبُوهُ قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَوَاللَّهِ لَوْلَا ‏ ‏الِاسْتِحْيَاءُ يَوْمَئِذٍ أَنْ ‏ ‏يَأْثُرَ ‏ ‏أَصْحَابِي عَنِّي الْكَذِبَ لَكَذَبْتُهُ حِينَ سَأَلَنِي وَلَكِنِّي اسْتَحَيْتُ أَنْ ‏ ‏يُؤْثَرَ ‏ ‏عَنِّي الْكَذِبُ فَصَدَقْتُهُ عَنْهُ ثُمَّ قَالَ لِتَرْجُمَانِهِ قُلْ لَهُ كَيْفَ نَسَبُ هَذَا الرَّجُلِ فِيكُمْ قَالَ قُلْتُ هُوَ فِينَا ذُو نَسَبٍ قَالَ فَهَلْ قَالَ هَذَا الْقَوْلَ مِنْكُمْ أَحَدٌ قَطُّ قَبْلَهُ قَالَ قُلْتُ لَا قَالَ فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ فِي الْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ قَالَ فَقُلْتُ لَا قَالَ فَهَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قَالَ قُلْتُ لَا قَالَ فَأَشْرَافُ النَّاسِ اتَّبَعُوهُ أَمْ ضُعَفَاؤُهُمْ قَالَ قُلْتُ بَلْ ضُعَفَاؤُهُمْ قَالَ فَيَزِيدُونَ أَمْ يَنْقُصُونَ قَالَ قُلْتُ بَلْ يَزِيدُونَ قَالَ فَهَلْ يَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ قَالَ قُلْتُ لَا قَالَ فَهَلْ يَغْدِرُ قَالَ قُلْتُ لَا وَنَحْنُ الْآنَ مِنْهُ فِي ‏ ‏مُدَّةٍ ‏ ‏وَنَحْنُ نَخَافُ ذَلِكَ قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏وَلَمْ تُمْكِنِّي كَلِمَةٌ أُدْخِلُ فِيهَا شَيْئًا أَنْتَقِصُهُ بِهِ غَيْرُهَا لَأَخَافُ أَنْ ‏ ‏يُؤْثَرَ ‏ ‏عَنِّي الْكَذِبُ قَالَ فَهَلْ قَاتَلْتُمُوهُ أَوْ قَاتَلَكُمْ قَالَ قُلْتُ نَعَمْ قَالَ كَيْفَ كَانَتْ حَرْبُكُمْ وَحَرْبُهُ قَالَ قُلْتُ كَانَتْ ‏ ‏دُوَلًا ‏ ‏سِجَالًا ‏ ‏نُدَالُ عَلَيْهِ الْمَرَّةَ ‏ ‏وَيُدَالُ ‏ ‏عَلَيْنَا الْأُخْرَى قَالَ فَبِمَ يَأْمُرُكُمْ قَالَ قُلْتُ يَأْمُرُنَا ‏ ‏أَنْ نَعْبُدَ اللَّهَ وَحْدَهُ وَلَا نُشْرِكَ بِهِ شَيْئًا وَيَنْهَانَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا وَيَأْمُرُنَا بِالصَّلَاةِ وَالصِّدْقِ وَالْعَفَافِ وَالْوَفَاءِ بِالْعَهْدِ وَأَدَاءِ الْأَمَانَةِ قَالَ فَقَالَ لِتَرْجُمَانِهِ حِينَ قُلْتُ لَهُ ذَلِكَ قُلْ لَهُ إِنِّي سَأَلْتُكَ عَنْ نَسَبِهِ فِيكُمْ فَزَعَمْتَ أَنَّهُ فِيكُمْ ذُو نَسَبٍ وَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي نَسَبِ قَوْمِهَا وَسَأَلْتُكَ هَلْ قَالَ هَذَا الْقَوْلَ أَحَدٌ مِنْكُمْ قَطُّ قَبْلَهُ فَزَعَمْتَ أَنْ لَا فَقُلْتُ لَوْ كَانَ أَحَدٌ مِنْكُمْ قَالَ هَذَا الْقَوْلَ قَبْلَهُ قُلْتُ رَجُلٌ ‏ ‏يَأْتَمُّ ‏ ‏بِقَوْلٍ قِيلَ قَبْلَهُ وَسَأَلْتُكَ هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ فَزَعَمْتَ أَنْ لَا فَقَدْ أَعْرِفُ أَنَّهُ لَمْ يَكُنْ ‏ ‏لِيَذَرَ ‏ ‏الْكَذِبَ عَلَى النَّاسِ وَيَكْذِبَ عَلَى اللَّهِ عَزَّ وَجَلَّ وَسَأَلْتُكَ هَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ فَزَعَمْتَ أَنْ لَا فَقُلْتُ لَوْ كَانَ مِنْ آبَائِهِ مَلِكٌ قُلْتُ رَجُلٌ يَطْلُبُ مُلْكَ آبَائِهِ وَسَأَلْتُكَ أَشْرَافُ النَّاسِ يَتَّبِعُونَهُ أَمْ ضُعَفَاؤُهُمْ فَزَعَمْتَ أَنَّ ضُعَفَاءَهُمْ اتَّبَعُوهُ وَهُمْ أَتْبَاعُ الرُّسُلِ وَسَأَلْتُكَ هَلْ يَزِيدُونَ أَمْ يَنْقُصُونَ فَزَعَمْتَ أَنَّهُمْ يَزِيدُونَ وَكَذَلِكَ الْإِيمَانُ ‏ ‏حَتَّى يَتِمَّ وَسَأَلْتُكَ هَلْ يَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ فَزَعَمْتَ أَنْ لَا وَكَذَلِكَ الْإِيمَانُ حِينَ يُخَالِطُ بَشَاشَةَ الْقُلُوبِ لَا يَسْخَطُهُ أَحَدٌ وَسَأَلْتُكَ هَلْ يَغْدِرُ فَزَعَمْتَ أَنْ لَا وَكَذَلِكَ الرُّسُلُ وَسَأَلْتُكَ هَلْ قَاتَلْتُمُوهُ وَقَاتَلَكُمْ فَزَعَمْتَ أَنْ قَدْ فَعَلَ وَأَنَّ حَرْبَكُمْ وَحَرْبَهُ يَكُونُ ‏ ‏دُوَلًا ‏ ‏يُدَالُ ‏ ‏عَلَيْكُمْ الْمَرَّةَ ‏ ‏وَتُدَالُونَ ‏ ‏عَلَيْهِ الْأُخْرَى وَكَذَلِكَ الرُّسُلُ تُبْتَلَى وَيَكُونُ لَهَا ‏ ‏الْعَاقِبَةُ ‏ ‏وَسَأَلْتُكَ بِمَاذَا يَأْمُرُكُمْ فَزَعَمْتَ أَنَّهُ يَأْمُرُكُمْ أَنْ تَعْبُدُوا اللَّهَ عَزَّ وَجَلَّ وَحْدَهُ لَا تُشْرِكُوا بِهِ شَيْئًا ‏ ‏وَيَنْهَاكُمْ عَمَّا كَانَ يَعْبُدُ آبَاؤُكُمْ وَيَأْمُرُكُمْ بِالصِّدْقِ وَالصَّلَاةِ وَالْعَفَافِ وَالْوَفَاءِ بِالْعَهْدِ وَأَدَاءِ الْأَمَانَةِ وَهَذِهِ صِفَةُ نَبِيٍّ قَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ وَلَكِنْ لَمْ أَظُنَّ أَنَّهُ مِنْكُمْ فَإِنْ يَكُنْ مَا قُلْتَ فِيهِ حَقًّا فَيُوشِكُ أَنْ يَمْلِكَ مَوْضِعَ قَدَمَيَّ هَاتَيْنِ وَاللَّهِ لَوْ أَرْجُو أَنْ أَخْلُصَ إِلَيْهِ ‏ ‏لَتَجَشَّمْتُ ‏ ‏لُقِيَّهُ وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمَيْهِ قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَ بِهِ فَقُرِئَ فَإِذَا فِيهِ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏ ‏مِنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى ‏ ‏هِرَقْلَ ‏ ‏عَظِيمِ ‏ ‏الرُّومِ ‏ ‏سَلَامٌ عَلَى مَنْ اتَّبَعَ الْهُدَى أَمَّا بَعْدُ فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ أَسْلِمْ تَسْلَمْ وَأَسْلِمْ يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ فَإِنْ ‏ ‏تَوَلَّيْتَ ‏ ‏فَعَلَيْكَ إِثْمُ ‏ ‏الْأَرِيسِيِّينَ ‏ ‏يَعْنِي الْأَكَّارَةَ ‏ ‏وَ ‏ { ‏يَا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ ‏} ‏قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَلَمَّا قَضَى مَقَالَتَهُ عَلَتْ أَصْوَاتُ الَّذِينَ حَوْلَهُ مِنْ عُظَمَاءِ ‏ ‏الرُّومِ ‏ ‏وَكَثُرَ لَغَطُهُمْ فَلَا أَدْرِي مَاذَا قَالُوا وَأَمَرَ بِنَا فَأُخْرِجْنَا قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَلَمَّا خَرَجْتُ مَعَ أَصْحَابِي وَخَلَصْتُ لَهُمْ قُلْتُ لَهُمْ أَمِرَ أَمْرُ ‏ ‏ابْنِ أَبِي كَبْشَةَ ‏ ‏هَذَا مَلِكُ ‏ ‏بَنِي الْأَصْفَرِ ‏ ‏يَخَافُهُ ‏ ‏قَالَ ‏ ‏أَبُو سُفْيَانَ ‏ ‏فَوَاللَّهِ مَا زِلْتُ ذَلِيلًا مُسْتَيْقِنًا أَنَّ أَمْرَهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللَّهُ قَلْبِي الْإِسْلَامَ وَأَنَا كَارِهٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[2253,2253,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّتِي ذَكَرَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏ذَكَرَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا نَائِمٌ رَأَيْتُ أَنَّهُ وُضِعَ فِي يَدَيَّ سِوَارَانِ مِنْ ذَهَبٍ فَفَظِعْتُهُمَا فَكَرِهْتُهُمَا وَأُذِنَ لِي فَنَفَخْتُهُمَا فَطَارَا فَأَوَّلْتُهُ كَذَّابَيْنِ يَخْرُجَانِ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَحَدُهُمَا ‏ ‏الْعَنْسِيُّ ‏ ‏الَّذِي قَتَلَهُ ‏ ‏فَيْرُوزُ ‏ ‏بِالْيَمَنِ ‏ ‏وَالْآخَرُ ‏ ‏مُسَيْلِمَةُ ‏","","",""],[2254,2254,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏صَالِحٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ كَعْبِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏خَرَجَ مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجَعِهِ الَّذِي تُوُفِّيَ فِيهِ فَقَالَ النَّاسُ يَا ‏ ‏أَبَا حَسَنٍ ‏ ‏كَيْفَ أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَصْبَحَ بِحَمْدِ اللَّهِ بَارِئًا قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَأَخَذَ بِيَدِهِ ‏ ‏عَبَّاسُ بْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ أَلَا ‏ ‏تَرَى أَنْتَ وَاللَّهِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيُتَوَفَّى فِي وَجَعِهِ هَذَا إِنِّي أَعْرِفُ وُجُوهَ ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏عِنْدَ الْمَوْتِ فَاذْهَبْ بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلْنَسْأَلْهُ فِيمَنْ هَذَا الْأَمْرُ فَإِنْ كَانَ فِينَا عَلِمْنَا ذَلِكَ وَإِنْ كَانَ فِي غَيْرِنَا كَلَّمْنَاهُ فَأَوْصَى بِنَا فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَاللَّهِ لَئِنْ سَأَلْنَاهَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنَعَنَاهَا لَا يُعْطِينَاهَا النَّاسُ أَبَدًا فَوَاللَّهِ لَا أَسْأَلُهُ أَبَدًا ‏","","",""],[2255,2255,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏الْمِسْوَرَ بْنَ مَخْرَمَةَ ‏ ‏وَعَبْدَ الرَّحْمَنِ بْنَ عَبْدٍ الْقَارِيَّ ‏ ‏حَدَّثَاهُ أَنَّهُمَا سَمِعَا ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏هِشَامَ بْنَ حَكِيمِ بْنِ حِزَامٍ ‏ ‏يَقْرَأُ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَحَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقْرَأَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَلَى حَرْفٍ فَرَاجَعْتُهُ فَلَمْ أَزَلْ أَسْتَزِيدُهُ وَيَزِيدُنِي حَتَّى انْتَهَى إِلَى سَبْعَةِ أَحْرُفٍ ‏","","",""],[2256,2256,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ وَقَدْ ‏ ‏نَاهَزْتُ ‏ ‏الْحُلُمَ ‏ ‏أَسِيرُ عَلَى ‏ ‏أَتَانٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمٌ ‏ ‏يُصَلِّي لِلنَّاسِ ‏ ‏يَعْنِي حَتَّى صِرْتُ بَيْنَ يَدَيْ بَعْضِ الصَّفِّ الْأَوَّلِ ثُمَّ نَزَلْتُ عَنْهَا فَرَتَعَتْ فَصَفَفْتُ مَعَ النَّاسِ وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2257,2257,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءِ بْنِ عَيَّاشِ بْنِ عَلْقَمَةَ ‏ ‏أَخُو ‏ ‏بَنِي عَامِرِ بْنِ لُؤَيٍّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بَيْتَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِغَدِ يَوْمِ الْجُمُعَةِ قَالَ وَكَانَتْ ‏ ‏مَيْمُونَةُ ‏ ‏قَدْ أَوْصَتْ لَهُ بِهِ فَكَانَ إِذَا صَلَّى الْجُمُعَةَ بُسِطَ لَهُ فِيهِ ثُمَّ انْصَرَفَ إِلَيْهِ فَجَلَسَ فِيهِ لِلنَّاسِ قَالَ فَسَأَلَهُ رَجُلٌ وَأَنَا أَسْمَعُ عَنْ الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ مِنْ الطَّعَامِ قَالَ فَرَفَعَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَدَهُ إِلَى عَيْنَيْهِ وَقَدْ كُفَّ بَصَرُهُ فَقَالَ بَصُرَ عَيْنَايَ هَاتَانِ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ لِصَلَاةِ الظُّهْرِ فِي بَعْضِ حُجَرِهِ ثُمَّ دَعَا ‏ ‏بِلَالٌ ‏ ‏إِلَى الصَّلَاةِ فَنَهَضَ خَارِجًا فَلَمَّا وَقَفَ عَلَى بَابِ الْحُجْرَةِ لَقِيَتْهُ هَدِيَّةٌ مِنْ خُبْزٍ وَلَحْمٍ بَعَثَ بِهَا إِلَيْهِ بَعْضُ أَصْحَابِهِ قَالَ فَرَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَنْ مَعَهُ وَوُضِعَتْ لَهُمْ فِي الْحُجْرَةِ قَالَ فَأَكَلَ وَأَكَلُوا مَعَهُ قَالَ ثُمَّ نَهَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَنْ مَعَهُ إِلَى الصَّلَاةِ وَمَا مَسَّ وَلَا أَحَدٌ مِمَّنْ كَانَ مَعَهُ مَاءً قَالَ ثُمَّ صَلَّى بِهِمْ ‏ ‏وَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا عَقَلَ مِنْ أَمْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِرَهُ ‏","","",""],[2258,2258,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكْيرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ طَهْمَانَ ‏ ‏حَدَّثَنِي ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏طَافَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى بَعِيرِهِ فَكُلَّمَا أَتَى عَلَى الرُّكْنِ أَشَارَ إِلَيْهِ وَكَبَّرَ ‏","","",""],[2259,2259,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الْحَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏خَتِينٌ ‏","","",""],[2260,2260,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ بْنِ نُوَيْفِعٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بَعَثَتْ ‏ ‏بَنُو سَعْدِ بْنِ بَكْرٍ ‏ ‏ضِمَامَ بْنَ ثَعْلَبَةَ ‏ ‏وَافِدًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَدِمَ عَلَيْهِ وَأَنَاخَ بَعِيرَهُ عَلَى بَابِ الْمَسْجِدِ ثُمَّ ‏ ‏عَقَلَهُ ‏ ‏ثُمَّ دَخَلَ الْمَسْجِدَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فِي أَصْحَابِهِ وَكَانَ ‏ ‏ضِمَامٌ ‏ ‏رَجُلًا جَلْدًا أَشْعَرَ ذَا غَدِيرَتَيْنِ فَأَقْبَلَ حَتَّى وَقَفَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَصْحَابِهِ فَقَالَ أَيُّكُمْ ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا ‏ ‏ابْنُ عَبْدِ الْمُطَّلِبِ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ نَعَمْ فَقَالَ ‏ ‏ابْنَ عَبْدِ الْمُطَّلِبِ ‏ ‏إِنِّي سَائِلُكَ وَمُغَلِّظٌ فِي الْمَسْأَلَةِ فَلَا تَجِدَنَّ فِي نَفْسِكَ قَالَ لَا أَجِدُ فِي نَفْسِي فَسَلْ عَمَّا بَدَا لَكَ قَالَ ‏ ‏أَنْشُدُكَ ‏ ‏اللَّهَ إِلَهَكَ وَإِلَهَ مَنْ كَانَ قَبْلَكَ وَإِلَهَ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ بَعَثَكَ إِلَيْنَا رَسُولًا فَقَالَ اللَّهُمَّ نَعَمْ قَالَ فَأَنْشُدُكَ اللَّهَ إِلَهَكَ وَإِلَهَ مَنْ كَانَ قَبْلَكَ وَإِلَهَ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ تَأْمُرَنَا أَنْ نَعْبُدَهُ وَحْدَهُ لَا نُشْرِكُ بِهِ شَيْئًا وَأَنْ نَخْلَعَ هَذِهِ ‏ ‏الْأَنْدَادَ ‏ ‏الَّتِي كَانَتْ آبَاؤُنَا يَعْبُدُونَ مَعَهُ قَالَ اللَّهُمَّ نَعَمْ قَالَ ‏ ‏فَأَنْشُدُكَ ‏ ‏اللَّهَ إِلَهَكَ وَإِلَهَ مَنْ كَانَ قَبْلَكَ وَإِلَهَ مَنْ هُوَ كَائِنٌ بَعْدَكَ ‏ ‏آللَّهُ أَمَرَكَ أَنْ نُصَلِّيَ هَذِهِ الصَّلَوَاتِ الْخَمْسَ قَالَ اللَّهُمَّ نَعَمْ قَالَ ثُمَّ جَعَلَ يَذْكُرُ فَرَائِضَ الْإِسْلَامِ فَرِيضَةً فَرِيضَةً الزَّكَاةَ وَالصِّيَامَ وَالْحَجَّ وَشَرَائِعَ الْإِسْلَامِ كُلَّهَا ‏ ‏يُنَاشِدُهُ ‏ ‏عِنْدَ كُلِّ فَرِيضَةٍ كَمَا ‏ ‏يُنَاشِدُهُ ‏ ‏فِي الَّتِي قَبْلَهَا حَتَّى إِذَا فَرَغَ قَالَ فَإِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ سَيِّدَنَا ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏وَسَأُؤَدِّي هَذِهِ الْفَرَائِضَ وَأَجْتَنِبُ مَا نَهَيْتَنِي عَنْهُ ثُمَّ لَا أَزِيدُ وَلَا أَنْقُصُ قَالَ ثُمَّ انْصَرَفَ رَاجِعًا إِلَى بَعِيرِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَلَّى ‏ ‏إِنْ يَصْدُقْ ذُو ‏ ‏الْعَقِيصَتَيْنِ ‏ ‏يَدْخُلْ الْجَنَّةَ قَالَ فَأَتَى إِلَى بَعِيرِهِ فَأَطْلَقَ عِقَالَهُ ثُمَّ خَرَجَ حَتَّى قَدِمَ عَلَى قَوْمِهِ فَاجْتَمَعُوا إِلَيْهِ ‏ ‏فَكَانَ أَوَّلَ مَا تَكَلَّمَ بِهِ أَنْ قَالَ بِئْسَتِ اللَّاتُ وَالْعُزَّى قَالُوا ‏ ‏مَهْ ‏ ‏يَا ‏ ‏ضِمَامُ ‏ ‏اتَّقِ الْبَرَصَ ‏ ‏وَالْجُذَامَ ‏ ‏اتَّقِ الْجُنُونَ قَالَ وَيْلَكُمْ إِنَّهُمَا وَاللَّهِ لَا يَضُرَّانِ وَلَا يَنْفَعَانِ إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ بَعَثَ رَسُولًا وَأَنْزَلَ عَلَيْهِ كِتَابًا اسْتَنْقَذَكُمْ بِهِ مِمَّا كُنْتُمْ فِيهِ وَإِنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ إِنِّي قَدْ جِئْتُكُمْ مِنْ عِنْدِهِ بِمَا أَمَرَكُمْ بِهِ وَنَهَاكُمْ عَنْهُ قَالَ فَوَاللَّهِ مَا أَمْسَى مِنْ ذَلِكَ الْيَوْمِ وَفِي حَاضِرِهِ رَجُلٌ وَلَا امْرَأَةٌ إِلَّا مُسْلِمًا ‏ ‏قَالَ ‏ ‏يَقُولُ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَمَا سَمِعْنَا بِوَافِدِ قَوْمٍ كَانَ أَفْضَلَ مِنْ ‏ ‏ضِمَامِ بْنِ ثَعْلَبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ بْنِ نُوَيْفِعٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏فَذَكَرَهُ مُخْتَصَرًا ‏","","",""],[2261,2261,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا كَانَتْ صَلَاةُ الْخَوْفِ إِلَّا كَصَلَاةِ ‏ ‏أَحْرَاسِكُمْ الْيَوْمَ خَلْفَ أَئِمَّتِكُمْ إِلَّا أَنَّهَا كَانَتْ ‏ ‏عُقْبًا ‏ ‏قَامَتْ طَائِفَةٌ وَهُمْ جَمْعٌ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَجَدَتْ مَعَهُ طَائِفَةٌ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَجَدَ الَّذِينَ كَانُوا قِيَامًا لِأَنْفُسِهِمْ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَامُوا مَعَهُ جَمِيعًا ثُمَّ رَكَعَ وَرَكَعُوا مَعَهُ جَمِيعًا ثُمَّ سَجَدَ فَسَجَدَ مَعَهُ الَّذِينَ كَانُوا قِيَامًا أَوَّلَ مَرَّةٍ وَقَامَ الْآخَرُونَ الَّذِينَ كَانُوا سَجَدُوا مَعَهُ أَوَّلَ مَرَّةٍ فَلَمَّا جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِينَ سَجَدُوا مَعَهُ فِي آخِرِ صَلَاتِهِمْ سَجَدَ الَّذِينَ كَانُوا قِيَامًا لِأَنْفُسِهِمْ ثُمَّ جَلَسُوا فَجَمَعَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالسَّلَامِ ‏","","",""],[2262,2262,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏طَاوُسٍ الْيَمَانِيِّ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏يَزْعُمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اغْتَسِلُوا يَوْمَ الْجُمُعَةِ وَاغْسِلُوا رُءُوسَكُمْ وَإِنْ لَمْ تَكُونُوا جُنُبًا وَمَسُّوا مِنْ الطِّيبِ قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَّا الطِّيبُ فَلَا أَدْرِي وَأَمَّا الْغُسْلُ فَنَعَمْ ‏","","",""],[2263,2263,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ الْحَضْرَمِيُّ ‏ ‏وَمُحَمَّدُ بْنُ الْوَلِيدِ بْنِ نُوَيْفِعٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏كِلَاهُمَا ‏ ‏حَدَّثَنِي عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فِي بُرْدٍ لَهُ ‏ ‏حَضْرَمِيٍّ ‏ ‏مُتَوَشِّحَهُ ‏ ‏مَا عَلَيْهِ غَيْرُهُ ‏","","",""],[2264,2264,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَقَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ مَطِيرٍ وَهُوَ يَتَّقِي الطِّينَ إِذَا سَجَدَ بِكِسَاءٍ يَجْعَلُهُ دُونَ يَدَيْهِ إِلَى الْأَرْضِ إِذَا سَجَدَ ‏","","",""],[2265,2265,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْعَبَّاسُ بْنُ عَبْدِ اللَّهِ بْنِ مَعْبَدِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَهْلِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي رَكْعَتَيْهِ قَبْلَ الْفَجْرِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَالْآيَتَيْنِ مِنْ خَاتِمَةِ ‏ ‏الْبَقَرَةِ ‏ ‏فِي الرَّكْعَةِ الْأُولَى وَفِي الرَّكْعَةِ الْآخِرَةِ ‏ ‏بِفَاتِحَةِ الْقُرْآنِ ‏ ‏وَبِالْآيَةِ مِنْ ‏ ‏آلِ ‏ ‏عِمْرَانَ ‏ { ‏قُلْ يَا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ ‏} ‏حَتَّى يَخْتِمَ ‏ ‏الْآيَةَ ‏","","",""],[2266,2266,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏دَاوُدُ بْنُ الْحُصَيْنِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏طَلَّقَ ‏ ‏رُكَانَةُ بْنُ عَبْدِ يَزِيدَ ‏ ‏أَخُو ‏ ‏الْمُطَّلِبِ ‏ ‏امْرَأَتَهُ ثَلَاثًا فِي مَجْلِسٍ وَاحِدٍ فَحَزِنَ عَلَيْهَا حُزْنًا شَدِيدًا قَالَ فَسَأَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ طَلَّقْتَهَا قَالَ طَلَّقْتُهَا ثَلَاثًا قَالَ فَقَالَ فِي مَجْلِسٍ وَاحِدٍ قَالَ نَعَمْ قَالَ فَإِنَّمَا تِلْكَ وَاحِدَةٌ فَارْجِعْهَا إِنْ شِئْتَ قَالَ فَرَجَعَهَا ‏ ‏فَكَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَرَى أَنَّمَا الطَّلَاقُ عِنْدَ كُلِّ طُهْرٍ ‏","","",""],[2267,2267,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ أُمَيَّةَ بْنِ عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ الْمَكِّيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أُصِيبَ إِخْوَانُكُمْ ‏ ‏بِأُحُدٍ ‏ ‏جَعَلَ اللَّهُ عَزَّ وَجَلَّ أَرْوَاحَهُمْ فِي أَجْوَافِ طَيْرٍ خُضْرٍ تَرِدُ أَنْهَارَ الْجَنَّةِ تَأْكُلُ مِنْ ثِمَارِهَا ‏ ‏وَتَأْوِي ‏ ‏إِلَى قَنَادِيلَ مِنْ ذَهَبٍ فِي ظِلِّ الْعَرْشِ فَلَمَّا وَجَدُوا طِيبَ مَشْرَبِهِمْ وَمَأْكَلِهِمْ وَحُسْنَ مُنْقَلَبِهِمْ قَالُوا يَا لَيْتَ إِخْوَانَنَا يَعْلَمُونَ بِمَا صَنَعَ اللَّهُ لَنَا لِئَلَّا يَزْهَدُوا فِي الْجِهَادِ وَلَا ‏ ‏يَنْكُلُوا ‏ ‏عَنْ الْحَرْبِ فَقَالَ اللَّهُ عَزَّ وَجَلَّ أَنَا أُبَلِّغُهُمْ عَنْكُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ هَؤُلَاءِ الْآيَاتِ عَلَى رَسُولِهِ ‏ { ‏وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ أَمْوَاتًا بَلْ أَحْيَاءٌ ‏} ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[2268,2268,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ فُضَيْلٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ لَبِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشُّهَدَاءُ عَلَى بَارِقِ نَهَرٍ بِبَابِ الْجَنَّةِ فِي قُبَّةٍ خَضْرَاءَ يَخْرُجُ عَلَيْهِمْ رِزْقُهُمْ مِنْ الْجَنَّةِ بُكْرَةً وَعَشِيًّا ‏","","",""],[2269,2269,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَشَى مَعَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بَقِيعِ الْغَرْقَدِ ‏ ‏ثُمَّ وَجَّهَهُمْ وَقَالَ ‏ ‏انْطَلِقُوا عَلَى اسْمِ اللَّهِ اللَّهُمَّ أَعِنْهُمْ ‏ ‏يَعْنِي النَّفَرَ الَّذِينَ وَجَّهَهُمْ إِلَى ‏ ‏كَعْبِ بْنِ الْأَشْرَفِ ‏","","",""],[2270,2270,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ فَحَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ثُمَّ مَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِسَفَرِهِ وَاسْتَخْلَفَ عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏أَبَا رُهْمٍ كُلْثُومَ بْنَ حُصَيْنِ بْنِ عُتْبَةَ بْنِ خَلَفٍ الْغِفَارِيَّ ‏ ‏وَخَرَجَ لِعَشْرٍ مَضَيْنَ مِنْ رَمَضَانَ ‏ ‏فَصَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَامَ النَّاسُ مَعَهُ حَتَّى إِذَا كَانَ ‏ ‏بِالْكَدِيدِ ‏ ‏مَاءٍ بَيْنَ ‏ ‏عُسْفَانَ ‏ ‏وَأَمْجٍ أَفْطَرَ ثُمَّ مَضَى حَتَّى نَزَلَ ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏فِي عَشَرَةِ آلَافٍ مِنْ الْمُسْلِمِينَ ‏","","",""],[2271,2271,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبَانُ بْنُ صَالِحٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي نَجِيجٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏وَمُجَاهِدٍ أَبِي الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏فِي سَفَرِهِ وَهُوَ حَرَامٌ ‏","","",""],[2272,2272,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏ابْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏ذُكِرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ وَقَصَتْهُ ‏ ‏رَاحِلَتُهُ ‏ ‏وَهُوَ مُحْرِمٌ فَقَالَ ‏ ‏كَفِّنُوهُ وَلَا تُغَطُّوا رَأْسَهُ وَلَا تُمِسُّوهُ طِيبًا فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ وَهُوَ يُلَبِّي أَوْ وَهُوَ ‏ ‏يُهِلُّ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏بِإِسْنَادِهِ إِلَّا أَنَّهُ قَالَ وَلَا تُغَطُّوا وَجْهَهُ ‏","","",""],[2273,2273,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏لَا هِجْرَةَ يَقُولُ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ وَإِنْ ‏ ‏اسْتُنْفِرْتُمْ ‏ ‏فَانْفِرُوا ‏","","",""],[2274,2274,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضَعَ يَدَهُ عَلَى كَتِفِي ‏ ‏أَوْ عَلَى ‏ ‏مَنْكِبِي ‏ ‏شَكَّ ‏ ‏سَعِيدٌ ‏ ‏ثُمَّ قَالَ ‏ ‏اللَّهُمَّ ‏ ‏فَقِّهْهُ فِي الدِّينِ وَعَلِّمْهُ ‏ ‏التَّأْوِيلَ ‏","","",""],[2275,2275,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِهَذَا الْحَجَرِ لِسَانًا وَشَفَتَيْنِ يَشْهَدُ لِمَنْ اسْتَلَمَهُ يَوْمَ الْقِيَامَةِ بِحَقٍّ ‏","","",""],[2276,2276,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَامَ ‏ ‏بِمَكَّةَ ‏ ‏خَمْسَ عَشْرَةَ سَنَةً ثَمَانِ سِنِينَ ‏ ‏أَوْ سَبْعًا ‏ ‏يَرَى الضَّوْءَ وَيَسْمَعُ الصَّوْتَ وَثَمَانِيًا ‏ ‏أَوْ سَبْعًا ‏ ‏يُوحَى إِلَيْهِ وَأَقَامَ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَشْرًا ‏","","",""],[2277,2277,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَخْطُبُ إِلَى جِذْعِ نَخْلَةٍ فَلَمَّا اتَّخَذَ الْمِنْبَرَ تَحَوَّلَ إِلَى الْمِنْبَرِ ‏ ‏فَحَنَّ الْجِذْعُ حَتَّى أَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْتَضَنَهُ فَسَكَنَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ لَمْ أَحْتَضِنْهُ لَحَنَّ إِلَى يَوْمِ الْقِيَامَةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ مَعْنَاهُ ‏","","",""],[2278,2278,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ فِيمَا يَرَى النَّائِمُ مَلَكَانِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رِجْلَيْهِ وَالْآخَرُ عِنْدَ رَأْسِهِ فَقَالَ الَّذِي عِنْدَ رِجْلَيْهِ لِلَّذِي عِنْدَ رَأْسِهِ اضْرِبْ مَثَلَ هَذَا وَمَثَلَ أُمَّتِهِ فَقَالَ إِنَّ مَثَلَهُ وَمَثَلَ أُمَّتِهِ كَمَثَلِ قَوْمٍ سَفْرٍ انْتَهَوْا إِلَى رَأْسِ مَفَازَةٍ فَلَمْ يَكُنْ مَعَهُمْ مِنْ الزَّادِ مَا يَقْطَعُونَ بِهِ الْمَفَازَةَ وَلَا مَا يَرْجِعُونَ بِهِ فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ أَتَاهُمْ رَجُلٌ فِي حُلَّةٍ ‏ ‏حِبَرَةٍ ‏ ‏فَقَالَ أَرَأَيْتُمْ إِنْ وَرَدْتُ بِكُمْ رِيَاضًا مُعْشِبَةً وَحِيَاضًا رُوَاءً أَتَتَّبِعُونِي فَقَالُوا نَعَمْ قَالَ فَانْطَلَقَ بِهِمْ فَأَوْرَدَهُمْ رِيَاضًا مُعْشِبَةً وَحِيَاضًا رُوَاءً فَأَكَلُوا وَشَرِبُوا وَسَمِنُوا فَقَالَ لَهُمْ أَلَمْ أَلْقَكُمْ عَلَى تِلْكَ الْحَالِ فَجَعَلْتُمْ لِي إِنْ وَرَدْتُ بِكُمْ رِيَاضًا مُعْشِبَةً وَحِيَاضًا رُوَاءً أَنْ تَتَّبِعُونِي فَقَالُوا بَلَى قَالَ فَإِنَّ بَيْنَ أَيْدِيكُمْ رِيَاضًا أَعْشَبَ مِنْ هَذِهِ وَحِيَاضًا هِيَ أَرْوَى مِنْ هَذِهِ فَاتَّبِعُونِي قَالَ فَقَالَتْ طَائِفَةٌ صَدَقَ وَاللَّهِ لَنَتَّبِعَنَّهُ وَقَالَتْ طَائِفَةٌ قَدْ رَضِينَا بِهَذَا نُقِيمُ عَلَيْهِ ‏","","",""],[2279,2279,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَمَانٍ ‏ ‏عَنْ ‏ ‏حَسَنِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمَاءُ ‏ ‏مَاءُ غُسْلِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ غَسَّلُوهُ بَعْدَ وَفَاتِهِ يَسْتَنْقِعُ فِي جُفُونِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ ‏ ‏عَلِيٌّ ‏ ‏يَحْسُوهُ ‏","","",""],[2280,2280,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الضَّحَّاكِ بْنِ مُزَاحِمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِذَا لَبَّى يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ قَالَ وَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏انْتَهِ إِلَيْهَا فَإِنَّهَا تَلْبِيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2281,2281,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏التَّمِيمِيِّ ‏ ‏الَّذِي يُحْدِثُ التَّفْسِيرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ خَلْفِهِ ‏ ‏فَرَأَيْتُ بَيَاضَ إِبْطَيْهِ وَهُوَ مُجَخٍّ قَدْ ‏ ‏فَرَّجَ ‏ ‏يَدَيْهِ ‏","","",""],[2282,2282,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكَلَ كَتِفَ شَاةٍ ثُمَّ صَلَّى وَلَمْ يُعِدْ الْوُضُوءَ ‏","","",""],[2283,2283,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ظِلِّ حُجْرَةٍ مِنْ حُجَرِهِ وَعِنْدَهُ ‏ ‏نَفَرٌ ‏ ‏مِنْ الْمُسْلِمِينَ قَدْ كَادَ يَقْلِصُ عَنْهُمْ الظِّلُّ قَالَ فَقَالَ إِنَّهُ ‏ ‏سَيَأْتِيكُمْ إِنْسَانٌ يَنْظُرُ إِلَيْكُمْ بِعَيْنَيْ ‏ ‏شَيْطَانٍ فَإِذَا أَتَاكُمْ فَلَا تُكَلِّمُوهُ قَالَ فَجَاءَ رَجُلٌ أَزْرَقُ فَدَعَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَلَّمَهُ قَالَ عَلَامَ تَشْتُمُنِي أَنْتَ وَفُلَانٌ وَفُلَانٌ نَفَرٌ دَعَاهُمْ بِأَسْمَائِهِمْ قَالَ فَذَهَبَ الرَّجُلُ فَدَعَاهُمْ فَحَلَفُوا بِاللَّهِ وَاعْتَذَرُوا إِلَيْهِ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَحْلِفُونَ لَهُ كَمَا يَحْلِفُونَ لَكُمْ وَيَحْسَبُونَ ‏} ‏الْآيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فِي ظِلِّ حُجْرَةٍ قَدْ كَادَ يَقْلِصُ عَنْهُ الظِّلُّ فَذَكَرَهُ ‏","","",""],[2284,2284,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلَانِ حَاجَتُهُمَا وَاحِدَةٌ فَتَكَلَّمَ أَحَدُهُمَا فَوَجَدَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏فِيهِ إِخْلَافًا فَقَالَ لَهُ أَلَا تَسْتَاكُ فَقَالَ إِنِّي لَأَفْعَلُ وَلَكِنِّي لَمْ أَطْعَمْ طَعَامًا مُنْذُ ثَلَاثٍ ‏ ‏فَأَمَرَ بِهِ رَجُلًا ‏ ‏فَآوَاهُ ‏ ‏وَقَضَى لَهُ حَاجَتَهُ ‏","","",""],[2285,2285,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏قَابُوسَ بْنِ أَبِي ظَبْيَانَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏قُلْنَا ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَرَأَيْتَ قَوْلَ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ ‏} ‏مَا عَنَى بِذَلِكَ قَالَ قَامَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا ‏ ‏يُصَلِّي قَالَ فَخَطَرَ خَطْرَةً فَقَالَ الْمُنَافِقُونَ الَّذِينَ يُصَلُّونَ مَعَهُ أَلَا تَرَوْنَ لَهُ قَلْبَيْنِ قَالَ قَلْبٌ مَعَكُمْ وَقَلَبٌ مَعَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ ‏}","","",""],[2286,2286,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ يَعْنِي ابْنَ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏حَزَبَهُ ‏ ‏أَمْرٌ قَالَ لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْعَظِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْكَرِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ ثُمَّ يَدْعُو ‏","","",""],[2287,2287,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى بَعْضِ بَنَاتِهِ وَهِيَ فِي السَّوْقِ فَأَخَذَهَا وَوَضَعَهَا فِي حِجْرِهِ حَتَّى قُبِضَتْ فَدَمَعَتْ عَيْنَاهُ فَبَكَتْ ‏ ‏أُمُّ أَيْمَنَ ‏ ‏فَقِيلَ لَهَا أَتَبْكِينَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ أَلَا أَبْكِي وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْكِي قَالَ ‏ ‏إِنِّي لَمْ أَبْكِ وَهَذِهِ رَحْمَةٌ إِنَّ الْمُؤْمِنَ تَخْرُجُ نَفْسُهُ مِنْ بَيْنِ جَنْبَيْهِ وَهُوَ يَحْمَدُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[2288,2288,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُمْتُ أُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُمْتُ عَنْ يَسَارِهِ فَقَالَ بِيَدِهِ مِنْ وَرَائِهِ ‏ ‏حَتَّى أَخَذَ ‏ ‏بِعَضُدِي ‏ ‏أَوْ بِيَدِي ‏ ‏حَتَّى أَقَامَنِي عَنْ يَمِينِهِ ‏","","",""],[2289,2289,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ يَحْيَى الْمَعَافِرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏حَنَشٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُنْزِلَتْ هَذِهِ الْآيَةُ ‏ { ‏نِسَاؤُكُمْ حَرْثٌ لَكُمْ ‏} ‏فِي أُنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلُوهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ائْتِهَا عَلَى كُلِّ حَالٍ إِذَا كَانَ فِي الْفَرْجِ ‏","","",""],[2290,2290,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏قَزَعَةُ يَعْنِي ابْنَ سُوَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا أَسْأَلُكُمْ عَلَى مَا أَتَيْتُكُمْ بِهِ مِنْ ‏ ‏الْبَيِّنَاتِ ‏ ‏وَالْهُدَى أَجْرًا إِلَّا أَنْ تَوَدُّوا اللَّهَ وَأَنْ تَقَرَّبُوا إِلَيْهِ بِطَاعَتِهِ ‏","","",""],[2291,2291,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَتَمَضْمَضَ بِهَا ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثُمَّ أَخَذَ غَرْفَةً فَجَعَلَ بِهَا هَكَذَا ‏ ‏يَعْنِي أَضَافَهَا إِلَى يَدِهِ الْأُخْرَى ‏ ‏فَغَسَلَ بِهَا وَجْهَهُ ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُمْنَى ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ فَغَسَلَ بِهَا يَدَهُ الْيُسْرَى ثُمَّ مَسَحَ بِرَأْسِهِ ثُمَّ أَخَذَ غَرْفَةً مِنْ مَاءٍ ثُمَّ رَشَّ عَلَى رِجْلِهِ الْيُمْنَى حَتَّى غَسَلَهَا ثُمَّ أَخَذَ غَرْفَةً أُخْرَى فَغَسَلَ بِهَا رِجْلَهُ الْيُسْرَى ثُمَّ قَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَحْوَ هَذَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2292,2292,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ السَّبَخِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِابْنٍ لَهَا فَقَالَتْ إِنَّ ابْنِي هَذَا بِهِ جُنُونٌ يَأْخُذُهُ عِنْدَ غَدَائِنَا وَعَشَائِنَا فَيَخْبُثُ عَلَيْنَا ‏ ‏فَمَسَحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدْرَهُ وَدَعَا ‏ ‏فَثَعَّ ‏ ‏ثَعَّةً ‏ ‏يَعْنِي سَعَلَ ‏ ‏فَخَرَجَ مِنْ جَوْفِهِ مِثْلُ ‏ ‏الْجَرْوِ ‏ ‏الْأَسْوَدِ ‏","","",""],[2293,2293,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ الْغُسْلِ يَوْمَ الْجُمُعَةِ أَوَاجِبٌ هُوَ قَالَ لَا وَمَنْ شَاءَ اغْتَسَلَ وَسَأُحَدِّثُكُمْ عَنْ بَدْءِ الْغُسْلِ كَانَ النَّاسُ مُحْتَاجِينَ وَكَانُوا يَلْبَسُونَ الصُّوفَ وَكَانُوا يَسْقُونَ النَّخْلَ عَلَى ظُهُورِهِمْ وَكَانَ ‏ ‏مَسْجِدُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَيِّقًا مُتَقَارِبَ السَّقْفِ فَرَاحَ النَّاسُ فِي الصُّوفِ فَعَرِقُوا وَكَانَ مِنْبَرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَصِيرًا إِنَّمَا هُوَ ثَلَاثُ دَرَجَاتٍ فَعَرِقَ النَّاسُ فِي الصُّوفِ فَثَارَتْ ‏ ‏أَرْوَاحُهُمْ ‏ ‏أَرْوَاحُ الصُّوفِ ‏ ‏فَتَأَذَّى بَعْضُهُمْ بِبَعْضٍ حَتَّى بَلَغَتْ أَرْوَاحُهُمْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِذَا جِئْتُمْ الْجُمُعَةَ فَاغْتَسِلُوا وَلْيَمَسَّ أَحَدُكُمْ مِنْ أَطْيَبِ طِيبٍ إِنْ كَانَ عِنْدَهُ ‏","","",""],[2294,2294,"","","‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏وَقَعَ ‏ ‏عَلَى بَهِيمَةٍ فَاقْتُلُوهُ وَاقْتُلُوا الْبَهِيمَةَ ‏","","",""],[2295,2295,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي التَّقْدِيمِ وَالتَّأْخِيرِ فِي الرَّمْيِ وَالذَّبْحِ وَالْحَلْقِ لَا حَرَجَ ‏","","",""],[2296,2296,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ أَعْطِ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏الْحِكْمَةَ وَعَلِّمْهُ ‏ ‏التَّأْوِيلَ ‏","","",""],[2297,2297,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ رَبِيعَةَ بْنِ هِشَامِ بْنِ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ كِنَانَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَدِّي ‏ ‏هِشَامَ بْنَ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَعَثَ ‏ ‏الْوَلِيدُ ‏ ‏يَسْأَلُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏كَيْفَ صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الِاسْتِسْقَاءِ فَقَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَبَذِّلًا ‏ ‏مُتَخَشِّعًا فَأَتَى الْمُصَلَّى فَصَلَّى رَكْعَتَيْنِ كَمَا ‏ ‏يُصَلِّي فِي الْفِطْرِ وَالْأَضْحَى ‏","","",""],[2298,2298,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الشِّعْرِ حُكْمًا وَمِنْ ‏ ‏الْبَيَانِ ‏ ‏سِحْرًا ‏","","",""],[2299,2299,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا ‏ ‏صَفَرَ ‏ ‏وَلَا ‏ ‏هَامَ ‏ ‏فَذَكَرَ ‏ ‏سِمَاكٌ ‏ ‏أَنَّ ‏ ‏الصَّفَرَ ‏ ‏دَابَّةٌ تَكُونُ فِي بَطْنِ الْإِنْسَانِ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ تَكُونُ فِي الْإِبِلِ الْجَرِبَةُ فِي الْمِائَةِ فَتُجْرِبُهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَنْ أَعْدَى الْأَوَّلَ ‏","","",""],[2300,2300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكٌ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى الْخُمْرَةِ ‏","","",""],[2301,2301,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فَأَفَاضَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏وَأَمَرَهُمْ بِالسَّكِينَةِ ‏ ‏وَأَرْدَفَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏وَقَالَ يَا أَيُّهَا النَّاسُ عَلَيْكُمْ بِالسَّكِينَةِ وَالْوَقَارِ فَإِنَّ الْبِرَّ لَيْسَ ‏ ‏بِإِيجَافِ ‏ ‏الْإِبِلِ وَالْخَيْلِ فَمَا رَأَيْتُ نَاقَةً رَافِعَةً يَدَهَا ‏ ‏عَادِيَةً ‏ ‏حَتَّى بَلَغَتْ ‏ ‏جَمْعًا ‏ ‏ثُمَّ ‏ ‏أَرْدَفَ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏مِنْ ‏ ‏جَمْعٍ ‏ ‏إِلَى ‏ ‏مِنًى ‏ ‏وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ عَلَيْكُمْ بِالسَّكِينَةِ وَالْوَقَارِ فَإِنَّ الْبِرَّ لَيْسَ ‏ ‏بِإِيجَافِ ‏ ‏الْإِبِلِ وَالْخَيْلِ فَمَا رَأَيْتُ نَاقَةً رَافِعَةً يَدَهَا ‏ ‏عَادِيَةً ‏ ‏حَتَّى بَلَغَتْ ‏ ‏مِنًى ‏","","",""],[2302,2302,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏رَسُولُ اللَّهِ مِائَةَ ‏ ‏بَدَنَةٍ ‏ ‏فِيهَا جَمَلٌ أَحْمَرُ ‏ ‏لِأَبِي جَهْلٍ ‏ ‏فِي أَنْفِهِ بُرَّةٌ مِنْ فِضَّةٍ ‏","","",""],[2303,2303,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ فِي الْقُرْآنِ بِغَيْرِ عِلْمٍ ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[2304,2304,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً ‏ ‏مُغِيبًا ‏ ‏أَتَتْ رَجُلًا ‏ ‏تَشْتَرِي مِنْهُ شَيْئًا فَقَالَ ادْخُلِي ‏ ‏الدَّوْلَجَ ‏ ‏حَتَّى أُعْطِيَكِ فَدَخَلَتْ فَقَبَّلَهَا وَغَمَزَهَا فَقَالَتْ ‏ ‏وَيْحَكَ ‏ ‏إِنِّي ‏ ‏مُغِيبٌ ‏ ‏فَتَرَكَهَا وَنَدِمَ عَلَى مَا كَانَ مِنْهُ فَأَتَى ‏ ‏عُمَرَ ‏ ‏فَأَخْبَرَهُ بِالَّذِي صَنَعَ فَقَالَ ‏ ‏وَيْحَكَ ‏ ‏فَلَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏قَالَ فَإِنَّهَا ‏ ‏مُغِيبٌ ‏ ‏قَالَ فَأْتِ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَاسْأَلْهُ فَأَتَى ‏ ‏أَبَا بَكْرٍ ‏ ‏فَأَخْبَرَهُ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَيْحَكَ ‏ ‏لَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏قَالَ فَإِنَّهَا ‏ ‏مُغِيبٌ ‏ ‏قَالَ فَأْتِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبِرْهُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّهَا ‏ ‏مُغِيبٌ ‏ ‏قَالَ فَإِنَّهَا ‏ ‏مُغِيبٌ ‏ ‏فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَزَلَ الْقُرْآنُ ‏ { ‏وَأَقِمْ الصَّلَاةَ طَرَفَيْ النَّهَارِ ‏ ‏وَزُلَفًا ‏ ‏مِنْ اللَّيْلِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لِلذَّاكِرِينَ ‏} ‏قَالَ فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ أَهِيَ فِيَّ خَاصَّةً أَوْ فِي النَّاسِ عَامَّةً قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَا وَلَا نَعْمَةَ عَيْنٍ لَكَ بَلْ هِيَ لِلنَّاسِ عَامَّةً قَالَ فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ صَدَقَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏","","",""],[2305,2305,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏فِي قَوْلِ الْجِنِّ ‏ { ‏وَأَنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ كَادُوا يَكُونُونَ عَلَيْهِ لِبَدًا ‏} ‏قَالَ ‏ ‏لَمَّا رَأَوْهُ ‏ ‏يُصَلِّي بِأَصْحَابِهِ وَيُصَلُّونَ بِصَلَاتِهِ وَيَرْكَعُونَ بِرُكُوعِهِ وَيَسْجُدُونَ بِسُجُودِهِ تَعَجَّبُوا مِنْ طَوَاعِيَةِ أَصْحَابِهِ لَهُ فَلَمَّا رَجَعُوا إِلَى قَوْمِهِمْ قَالُوا إِنَّهُ لَمَّا قَامَ عَبْدُ اللَّهِ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُوهُ كَادُوا يَكُونُونَ عَلَيْهِ ‏ ‏لِبَدًا ‏","","",""],[2306,2306,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ عَاصِبًا رَأْسَهُ فِي خِرْقَةٍ فَقَعَدَ عَلَى الْمِنْبَرِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ إِنَّهُ ‏ ‏لَيْسَ أَحَدٌ أَمَنَّ عَلَيَّ فِي نَفْسِهِ وَمَالِهِ مِنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي قُحَافَةَ ‏ ‏وَلَوْ كُنْتُ مُتَّخِذًا مِنْ النَّاسِ خَلِيلًا لَاتَّخَذْتُ ‏ ‏أَبَا بَكْرٍ ‏ ‏خَلِيلًا وَلَكِنْ خُلَّةُ الْإِسْلَامِ أَفْضَلُ سُدُّوا عَنِّي كُلَّ ‏ ‏خَوْخَةٍ ‏ ‏فِي هَذَا الْمَسْجِدِ غَيْرَ ‏ ‏خَوْخَةِ ‏ ‏أَبِي بَكْرٍ ‏","","",""],[2307,2307,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَعْلَي بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَتَاهُ ‏ ‏مَاعِزُ بْنُ مَالِكٍ ‏ ‏قَالَ لَعَلَّكَ قَبَّلْتَ أَوْ ‏ ‏غَمَزْتَ ‏ ‏أَوْ نَظَرْتَ قَالَ لَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِكْتَهَا لَا يُكَنِّي قَالَ نَعَمْ قَالَ فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ ‏","","",""],[2308,2308,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنِ ‏ ‏الْمِنْهَالِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعَوِّذُ ‏ ‏الْحَسَنَ ‏ ‏وَالْحُسَيْنَ ‏ ‏فَيَقُولُ ‏ ‏أُعِيذُكُمَا بِكَلِمَةِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ ‏ ‏وَهَامَّةٍ ‏ ‏وَمِنْ كُلِّ عَيْنٍ ‏ ‏لَامَّةٍ ‏ ‏ثُمَّ يَقُولُ هَكَذَا كَانَ أَبِي ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏يُعَوِّذُ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَإِسْحَاقَ ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[2309,2309,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ وَعْلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قُلْتُ لَهُ إِنَّا نَغْزُو ‏ ‏فَنُؤْتَى ‏ ‏بِالْإِهَابِ ‏ ‏وَالْأَسْقِيَةِ ‏ ‏قَالَ مَا أَدْرِي مَا أَقُولُ لَكَ إِلَّا أَنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا ‏ ‏إِهَابٍ ‏ ‏دُبِغَ ‏ ‏فَقَدْ طَهُرَ ‏","","",""],[2310,2310,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعٍ وَلَا ‏ ‏يَكُفَّ ‏ ‏شَعْرًا وَلَا ثَوْبًا ‏","","",""],[2311,2311,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[2312,2312,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى طَعَامًا فَلَا يَبِعْهُ حَتَّى ‏ ‏يَسْتَوْفِيَهُ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَحْسِبُ كُلَّ شَيْءٍ بِمَنْزِلَةِ الطَّعَامِ ‏","","",""],[2313,2313,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُوا فِي ‏ ‏الْقَصْعَةِ ‏ ‏مِنْ جَوَانِبِهَا وَلَا تَأْكُلُوا مِنْ وَسَطِهَا فَإِنَّ الْبَرَكَةَ تَنْزِلُ فِي وَسَطِهَا ‏","","",""],[2314,2314,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَحْسِبُهُ رَفَعَهُ ‏ ‏قَالَ كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاءِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[2315,2315,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏فَجَعَلَتْ أَمْرَهَا إِلَى ‏ ‏الْعَبَّاسِ ‏ ‏فَزَوَّجَهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2316,2316,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَتَلَ الْمُسْلِمُونَ رَجُلًا مِنْ الْمُشْرِكِينَ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فَأَرْسَلُوا رَسُولًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْرَمُونَ الدِّيَةَ ‏ ‏بِجِيفَتِهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ لَخَبِيثٌ خَبِيثُ الدِّيَةِ خَبِيثُ ‏ ‏الْجِيفَةِ ‏ ‏فَخَلَّى بَيْنَهُمْ وَبَيْنَهُ ‏","","",""],[2317,2317,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ كِتَابًا بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏أَنْ يَعْقِلُوا مَعَاقِلَهُمْ وَأَنْ يَفْدُوا عَانِيَهُمْ بِالْمَعْرُوفِ وَالْإِصْلَاحِ بَيْنَ الْمُسْلِمِينَ ‏ ‏حَدَّثَنِي ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ ‏","","",""],[2318,2318,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏الْأَعْمَى عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَنَفَّلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيْفَهُ ذَا الْفَقَارِ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏وَهُوَ الَّذِي رَأَى فِيهِ الرُّؤْيَا يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ فِي سَيْفِي ذِي الْفَقَارِ فَلًّا ‏ ‏فَأَوَّلْتُهُ ‏ ‏فَلًّا يَكُونُ فِيكُمْ وَرَأَيْتُ أَنِّي مُرْدِفٌ كَبْشًا ‏ ‏فَأَوَّلْتُهُ ‏ ‏كَبْشَ الْكَتِيبَةِ وَرَأَيْتُ أَنِّي فِي دِرْعٍ حَصِينَةٍ ‏ ‏فَأَوَّلْتُهَا ‏ ‏الْمَدِينَةَ ‏ ‏وَرَأَيْتُ بَقَرًا تُذْبَحُ فَبَقَرٌ وَاللَّهِ خَيْرٌ فَبَقَرٌ وَاللَّهِ خَيْرٌ فَكَانَ الَّذِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2319,2319,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏قِرَاءَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ قَدْرَ مَا يَسْمَعُهُ مَنْ فِي الْحُجْرَةِ وَهُوَ فِي الْبَيْتِ ‏","","",""],[2320,2320,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ الْخَبَرُ ‏ ‏كَالْمُعَايَنَةِ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَخْبَرَ ‏ ‏مُوسَى ‏ ‏بِمَا صَنَعَ قَوْمُهُ فِي الْعِجْلِ فَلَمْ يُلْقِ الْأَلْوَاحَ فَلَمَّا عَايَنَ مَا صَنَعُوا أَلْقَى الْأَلْوَاحَ فَانْكَسَرَتْ ‏","","",""],[2321,2321,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ أَيُّكُمْ رَأَى الْكَوْكَبَ الَّذِي انْقَضَّ الْبَارِحَةَ قُلْتُ أَنَا ثُمَّ قُلْتُ أَمَا إِنِّي لَمْ أَكُنْ فِي صَلَاةٍ وَلَكِنِّي لُدِغْتُ قَالَ وَكَيْفَ فَعَلْتَ قُلْتُ اسْتَرْقَيْتُ قَالَ وَمَا حَمَلَكَ عَلَى ذَلِكَ قُلْتُ حَدِيثٌ ‏ ‏حَدَّثَنَاهُ ‏ ‏الشَّعْبِيُّ ‏ ‏عَنْ ‏ ‏بُرَيْدَةَ الْأَسْلَمِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ أَوْ حُمَةٍ ‏ ‏فَقَالَ ‏ ‏سَعِيدٌ يَعْنِي ابْنَ جُبَيْرٍ ‏ ‏قَدْ أَحْسَنَ مَنْ انْتَهَى إِلَى مَا سَمِعَ ثُمَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُرِضَتْ عَلَيَّ الْأُمَمُ فَرَأَيْتُ النَّبِيَّ وَمَعَهُ ‏ ‏الرَّهْطَ ‏ ‏وَالنَّبِيَّ وَمَعَهُ ‏ ‏الرَّجُلَ ‏ ‏وَالنَّبِيَّ وَلَيْسَ مَعَهُ أَحَدٌ إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ فَقُلْتُ هَذِهِ أُمَّتِي فَقِيلَ هَذَا ‏ ‏مُوسَى ‏ ‏وَقَوْمُهُ وَلَكِنْ انْظُرْ إِلَى الْأُفُقِ فَإِذَا سَوَادٌ عَظِيمٌ ثُمَّ قِيلَ انْظُرْ إِلَى هَذَا الْجَانِبِ الْآخَرِ فَإِذَا سَوَادٌ عَظِيمٌ فَقِيلَ هَذِهِ أُمَّتُكَ وَمَعَهُمْ سَبْعُونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ ثُمَّ نَهَضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ ‏ ‏فَخَاضَ ‏ ‏الْقَوْمُ فِي ذَلِكَ فَقَالُوا مَنْ هَؤُلَاءِ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ فَقَالَ بَعْضُهُمْ لَعَلَّهُمْ الَّذِينَ صَحِبُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ بَعْضُهُمْ لَعَلَّهُمْ الَّذِينَ وُلِدُوا فِي الْإِسْلَامِ وَلَمْ يُشْرِكُوا بِاللَّهِ شَيْئًا قَطُّ وَذَكَرُوا أَشْيَاءَ فَخَرَجَ إِلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا هَذَا الَّذِي كُنْتُمْ ‏ ‏تَخُوضُونَ ‏ ‏فِيهِ فَأَخْبَرُوهُ بِمَقَالَتِهِمْ فَقَالَ هُمْ الَّذِينَ لَا ‏ ‏يَكْتَوُونَ ‏ ‏وَلَا ‏ ‏يَسْتَرْقُونَ ‏ ‏وَلَا ‏ ‏يَتَطَيَّرُونَ ‏ ‏وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ فَقَامَ ‏ ‏عُكَّاشَةُ بْنُ مِحْصَنٍ الْأَسَدِيُّ ‏ ‏فَقَالَ أَنَا مِنْهُمْ يَا رَسُولَ اللَّهِ فَقَالَ أَنْتَ مِنْهُمْ ثُمَّ قَامَ الْآخَرُ فَقَالَ أَنَا مِنْهُمْ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبَقَكَ بِهَا ‏ ‏عُكَّاشَةُ ‏ ‏حَدَّثَنَا ‏ ‏شُجَاعٌ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏مِثْلَهُ ‏","","",""],[2322,2322,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا صَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا كَامِلًا قَطُّ غَيْرَ رَمَضَانَ ‏ ‏وَإِنْ كَانَ لَيَصُومُ إِذَا صَامَ حَتَّى يَقُولَ الْقَائِلُ وَاللَّهِ لَا يُفْطِرُ وَإِنْ كَانَ لَيُفْطِرُ إِذَا أَفْطَرَ حَتَّى يَقُولَ الْقَائِلُ وَاللَّهِ لَا يَصُومُ ‏","","",""],[2323,2323,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُؤَمَّلِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ الْأَوْدِيَةَ وَجَاءَ ‏ ‏بِهَدْيٍ ‏ ‏فَلَمْ يَكُنْ لَهُ بُدٌّ مِنْ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏وَيَسْعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏قَبْلَ أَنْ يَقِفَ ‏ ‏بِعَرَفَةَ ‏ ‏فَأَمَّا أَنْتُمْ يَا أَهْلَ ‏ ‏مَكَّةَ ‏ ‏فَأَخِّرُوا طَوَافَكُمْ حَتَّى تَرْجِعُوا ‏","","",""],[2324,2324,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنِ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا حُرِّمَتْ الْخَمْرُ قَالُوا يَا رَسُولَ اللَّهِ أَصْحَابُنَا الَّذِينَ مَاتُوا وَهُمْ يَشْرَبُونَهَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَيْسَ عَلَى الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ ‏ ‏جُنَاحٌ ‏ ‏فِيمَا طَعِمُوا ‏}","","",""],[2325,2325,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏قَالَ ‏ ‏حُدِّثْتُ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُدْمِنُ الْخَمْرِ إِنْ مَاتَ لَقِيَ اللَّهَ كَعَابِدِ وَثَنٍ ‏","","",""],[2326,2326,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏يُمْنَ ‏ ‏الْخَيْلِ فِي شُقْرِهَا ‏","","",""],[2327,2327,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏كُلْثُومِ بْنِ جَبْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَخَذَ اللَّهُ الْمِيثَاقَ مِنْ ظَهْرِ ‏ ‏آدَمَ ‏ ‏بِنَعْمَانَ ‏ ‏يَعْنِي ‏ ‏عَرَفَةَ ‏ ‏فَأَخْرَجَ مِنْ صُلْبِهِ كُلَّ ذُرِّيَّةٍ ذَرَأَهَا فَنَثَرَهُمْ بَيْنَ يَدَيْهِ كَالذَّرِّ ثُمَّ كَلَّمَهُمْ قِبَلًا قَالَ ‏ { ‏أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى شَهِدْنَا أَنْ تَقُولُوا يَوْمَ الْقِيَامَةِ إِنَّا كُنَّا عَنْ هَذَا غَافِلِينَ أَوْ تَقُولُوا إِنَّمَا أَشْرَكَ آبَاؤُنَا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ الْمُبْطِلُونَ ‏}","","",""],[2328,2328,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْفَجْرِ يَوْمَ الْجُمُعَةِ ‏ ‏الم تَنْزِيلُ ‏ ‏وَهَلْ أَتَى عَلَى الْإِنْسَانِ حِينٌ مِنْ الدَّهْرِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ ‏","","",""],[2329,2329,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنِ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الرَّجُلِ يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ يَتَصَدَّقُ بِنِصْفِ دِينَارٍ ‏","","",""],[2330,2330,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏عَجَّلَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ عَجَّلَ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏وَأَنَا مَعَهُمْ مِنْ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏إِلَى ‏ ‏جَمْرَةِ الْعَقَبَةِ ‏ ‏فَأَمَرَنَا أَنْ نَرْمِيَهَا حِينَ تَطْلُعُ الشَّمْسُ ‏","","",""],[2331,2331,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي الْعَطَّارَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏ثَقَلَةِ ‏ ‏وَضَعَفَةِ أَهْلِهِ لَيْلَةَ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فَصَلَّيْنَا الصُّبْحَ ‏ ‏بِمِنًى ‏ ‏وَرَمَيْنَا الْجَمْرَةَ ‏","","",""],[2332,2332,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءِ بْنِ عَلْقَمَةَ الْقُرَشِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْنَا بَيْتَ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْنَا فِيهِ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏فَذَكَرْنَا الْوُضُوءَ مِمَّا مَسَّتْ النَّارُ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ مِمَّا مَسَّتْهُ النَّارُ ثُمَّ ‏ ‏يُصَلِّي وَلَا يَتَوَضَّأُ فَقَالَ لَهُ بَعْضُنَا أَنْتَ رَأَيْتَهُ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ فَأَشَارَ بِيَدِهِ إِلَى عَيْنَيْهِ فَقَالَ بَصُرَ عَيْنَيَّ ‏","","",""],[2333,2333,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَخَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏عَلَى نَفَرٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَسُوقُ غَنَمًا لَهُ فَسَلَّمَ عَلَيْهِمْ فَقَالُوا مَا سَلَّمَ عَلَيْكُمْ إِلَّا لِيَتَعَوَّذَ مِنْكُمْ فَعَمَدُوا إِلَيْهِ فَقَتَلُوهُ وَأَخَذُوا غَنَمَهُ فَأَتَوْا بِهَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا ضَرَبْتُمْ فِي سَبِيلِ اللَّهِ فَتَبَيَّنُوا وَلَا تَقُولُوا لِمَنْ أَلْقَى إِلَيْكُمْ السَّلَامَ لَسْتَ مُؤْمِنًا ‏} ‏إِلَى آخِرِ ‏ ‏الْآيَةَ ‏","","",""],[2334,2334,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنْ الْمُنْكَرِ ‏} ‏قَالَ هُمْ الَّذِينَ هَاجَرُوا مَعَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2335,2335,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏لَمْ يَنْزِلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏عَرَفَاتٍ ‏ ‏وَجَمْعٍ ‏ ‏إِلَّا ‏ ‏لِيُهَرِيقَ ‏ ‏الْمَاءَ ‏","","",""],[2336,2336,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِيًا جَمِيعًا وَسَبْعًا جَمِيعًا ‏","","",""],[2337,2337,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْدَى فِي ‏ ‏بُدْنِهِ ‏ ‏بَعِيرًا كَانَ ‏ ‏لِأَبِي جَهْلٍ ‏ ‏فِي أَنْفِهِ ‏ ‏بُرَةٌ ‏ ‏مِنْ فِضَّةٍ ‏","","",""],[2338,2338,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَهَسَ ‏ ‏عَرْقًا ‏ ‏ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2339,2339,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏قَذَفَ ‏ ‏هِلَالُ بْنُ أُمَيَّةَ ‏ ‏امْرَأَتَهُ قِيلَ لَهُ وَاللَّهِ لَيَجْلِدَنَّكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِينَ جَلْدَةً قَالَ اللَّهُ أَعْدَلُ مِنْ ذَلِكَ أَنْ يَضْرِبَنِي ثَمَانِينَ ضَرْبَةً وَقَدْ عَلِمَ أَنِّي قَدْ رَأَيْتُ حَتَّى اسْتَيْقَنْتُ وَسَمِعْتُ حَتَّى اسْتَيْقَنْتُ لَا وَاللَّهِ لَا يَضْرِبُنِي أَبَدًا قَالَ ‏ ‏فَنَزَلَتْ ‏ ‏آيَةُ الْمُلَاعَنَةِ ‏","","",""],[2340,2340,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ابْنَةَ خِذَامٍ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَتْ أَنَّ أَبَاهَا زَوَّجَهَا وَهِيَ كَارِهَةٌ فَخَيَّرَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[2341,2341,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَأَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنِ ‏ ‏ابْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏أَحْمَدُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَكُونُ قَوْمٌ فِي آخِرِ الزَّمَانِ ‏ ‏يَخْضِبُونَ ‏ ‏بِهَذَا السَّوَادِ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏كَحَوَاصِلِ الْحَمَامِ ‏ ‏لَا يَرِيحُونَ رَائِحَةَ الْجَنَّةِ ‏","","",""],[2342,2342,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏حَضَرَتْ عِصَابَةٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏حَدِّثْنَا عَنْ ‏ ‏خِلَالٍ ‏ ‏نَسْأَلُكَ عَنْهُنَّ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ فَكَانَ فِيمَا سَأَلُوهُ أَيُّ الطَّعَامِ حَرَّمَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَلَى نَفْسِهِ قَبْلَ أَنْ تُنَزَّلَ التَّوْرَاةُ قَالَ ‏ ‏فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى ‏ ‏مُوسَى ‏ ‏هَلْ تَعْلَمُونَ أَنَّ ‏ ‏إِسْرَائِيلَ يَعْقُوبَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَرِضَ مَرَضًا شَدِيدًا فَطَالَ سَقَمُهُ فَنَذَرَ لِلَّهِ نَذْرًا لَئِنْ شَفَاهُ اللَّهُ مِنْ سَقَمِهِ لَيُحَرِّمَنَّ أَحَبَّ الشَّرَابِ إِلَيْهِ وَأَحَبَّ الطَّعَامِ إِلَيْهِ فَكَانَ أَحَبَّ الطَّعَامِ إِلَيْهِ ‏ ‏لُحْمَانُ الْإِبِلِ وَأَحَبَّ الشَّرَابِ إِلَيْهِ أَلْبَانُهَا فَقَالُوا اللَّهُمَّ نَعَمْ ‏","","",""],[2343,2343,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ وَهْرَامَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى بِسَاطٍ ‏","","",""],[2344,2344,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ الشِّعْرِ حُكْمًا وَإِنَّ مِنْ الْقَوْلِ سِحْرًا ‏","","",""],[2345,2345,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَلَى أُنَاسٍ قَدْ وَضَعُوا حَمَامَةً يَرْمُونَهَا فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَّخَذَ الرُّوحُ ‏ ‏غَرَضًا ‏","","",""],[2346,2346,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنَةً لَهُ ‏ ‏تَقْضِي ‏ ‏فَاحْتَضَنَهَا فَوَضَعَهَا بَيْنَ ثَدْيَيْهِ فَمَاتَتْ وَهِيَ بَيْنَ يَدَيْهِ فَصَاحَتْ ‏ ‏أُمُّ أَيْمَنَ ‏ ‏فَقِيلَ ‏ ‏أَتَبْكِي عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَلَسْتُ أَرَاكَ تَبْكِي يَا رَسُولَ اللَّهِ قَالَ ‏ ‏لَسْتُ أَبْكِي إِنَّمَا هِيَ رَحْمَةٌ إِنَّ الْمُؤْمِنَ بِكُلِّ خَيْرٍ عَلَى كُلِّ حَالٍ ‏ ‏إِنَّ نَفْسَهُ تَخْرُجُ مِنْ بَيْنِ جَنْبَيْهِ وَهُوَ يَحْمَدُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[2347,2347,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ بَذِيمَةَ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسُ بْنُ حَبْتَرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الْجَرِّ ‏ ‏الْأَبْيَضِ ‏ ‏وَالْجَرِّ ‏ ‏الْأَخْضَرِ ‏ ‏وَالْجَرِّ ‏ ‏الْأَحْمَرِ فَقَالَ إِنَّ أَوَّلَ مَنْ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفْدُ عَبْدِ الْقَيْسِ ‏ ‏فَقَالُوا إِنَّا نُصِيبُ مِنْ ‏ ‏الثُّفْلِ ‏ ‏فَأَيُّ الْأَسْقِيَةِ فَقَالَ ‏ ‏لَا تَشْرَبُوا فِي ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَاشْرَبُوا فِي الْأَسْقِيَةِ ثُمَّ قَالَ إِنَّ اللَّهَ حَرَّمَ عَلَيَّ ‏ ‏أَوْ حَرَّمَ ‏ ‏الْخَمْرَ وَالْمَيْسِرَ ‏ ‏وَالْكُوبَةَ ‏ ‏وَكُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قُلْتُ ‏ ‏لِعَلِيِّ بْنِ بَذِيمَةَ ‏ ‏مَا الْكُوبَةُ قَالَ الطَّبْلُ ‏","","",""],[2348,2348,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَيْنُ حَقٌّ تَسْتَنْزِلُ الْحَالِقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ الْعَدَنِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏دُوَيْدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏مِثْلَهُ ‏","","",""],[2349,2349,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏أَكْحَالِكُمُ ‏ ‏الْإِثْمِدُ ‏ ‏عِنْدَ النَّوْمِ يُنْبِتُ الشَّعْرَ ‏ ‏وَيَجْلُو ‏ ‏الْبَصَرَ وَخَيْرُ ثِيَابِكُمْ الْبَيَاضُ فَالْبَسُوهَا وَكَفِّنُوا فِيهَا مَوْتَاكُمْ ‏","","",""],[2350,2350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَلَاءُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَّخَذَ شَيْءٌ فِيهِ الرُّوحُ غَرَضًا ‏","","",""],[2351,2351,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعُ بْنُ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْأَيِّمُ ‏ ‏أَمْلَكُ بِأَمْرِهَا مِنْ ‏ ‏وَلِيِّهَا ‏ ‏وَالْبِكْرُ تُسْتَأْمَرُ فِي نَفْسِهَا وَصُمَاتُهَا إِقْرَارُهَا ‏","","",""],[2352,2352,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ الْجِنُّ يَسْمَعُونَ الْوَحْيَ فَيَسْتَمِعُونَ الْكَلِمَةَ فَيَزِيدُونَ فِيهَا عَشْرًا فَيَكُونُ مَا سَمِعُوا حَقًّا وَمَا زَادُوهُ بَاطِلًا وَكَانَتْ النُّجُومُ لَا ‏ ‏يُرْمَى بِهَا قَبْلَ ذَلِكَ فَلَمَّا بُعِثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ أَحَدُهُمْ لَا يَأْتِي مَقْعَدَهُ إِلَّا رُمِيَ بِشِهَابٍ يُحْرِقُ مَا أَصَابَ فَشَكَوْا ذَلِكَ إِلَى إِبْلِيسَ فَقَالَ مَا هَذَا إِلَّا مِنْ أَمْرٍ قَدْ حَدَثَ فَبَثَّ جُنُودَهُ فَإِذَا هُمْ بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بَيْنَ جَبَلَيْ ‏ ‏نَخْلَةَ ‏ ‏فَأَتَوْهُ فَأَخْبَرُوهُ فَقَالَ هَذَا الْحَدَثُ الَّذِي حَدَثَ فِي الْأَرْضِ ‏","","",""],[2353,2353,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ الْعِجْلِيُّ ‏ ‏وَكَانَتْ لَهُ هَيْئَةٌ رَأَيْنَاهُ عِنْدَ ‏ ‏حَسَنٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَتْ ‏ ‏يَهُودُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏إِنَّا نَسْأَلُكَ عَنْ خَمْسَةِ أَشْيَاءَ فَإِنْ أَنْبَأْتَنَا بِهِنَّ عَرَفْنَا أَنَّكَ نَبِيٌّ وَاتَّبَعْنَاكَ فَأَخَذَ عَلَيْهِمْ مَا أَخَذَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَلَى بَنِيهِ إِذْ قَالُوا ‏ { ‏اللَّهُ عَلَى مَا نَقُولُ وَكِيلٌ ‏} ‏قَالَ هَاتُوا قَالُوا أَخْبِرْنَا عَنْ عَلَامَةِ النَّبِيِّ قَالَ ‏ ‏تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ قَالُوا أَخْبِرْنَا كَيْفَ تُؤَنِّثُ الْمَرْأَةُ وَكَيْفَ تُذْكِرُ قَالَ يَلْتَقِي ‏ ‏الْمَاءَانِ ‏ ‏فَإِذَا عَلَا ‏ ‏مَاءُ ‏ ‏الرَّجُلِ ‏ ‏مَاءَ ‏ ‏الْمَرْأَةِ أَذْكَرَتْ وَإِذَا عَلَا ‏ ‏مَاءُ ‏ ‏الْمَرْأَةِ آنَثَتْ قَالُوا أَخْبِرْنَا مَا حَرَّمَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَلَى نَفْسِهِ قَالَ كَانَ يَشْتَكِي ‏ ‏عِرْقَ النَّسَا ‏ ‏فَلَمْ يَجِدْ شَيْئًا يُلَائِمُهُ إِلَّا أَلْبَانَ كَذَا وَكَذَا ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏بَعْضُهُمْ ‏ ‏يَعْنِي الْإِبِلَ ‏ ‏فَحَرَّمَ لُحُومَهَا قَالُوا صَدَقْتَ قَالُوا أَخْبِرْنَا مَا هَذَا الرَّعْدُ قَالَ مَلَكٌ مِنْ مَلَائِكَةِ اللَّهِ عَزَّ وَجَلَّ مُوَكَّلٌ بِالسَّحَابِ بِيَدِهِ ‏ ‏أَوْ فِي يَدِهِ ‏ ‏مِخْرَاقٌ مِنْ نَارٍ يَزْجُرُ بِهِ السَّحَابَ يَسُوقُهُ حَيْثُ أَمَرَ اللَّهُ قَالُوا فَمَا هَذَا الصَّوْتُ الَّذِي يُسْمَعُ قَالَ صَوْتُهُ قَالُوا صَدَقْتَ إِنَّمَا بَقِيَتْ وَاحِدَةٌ وَهِيَ الَّتِي نُبَايِعُكَ إِنْ أَخْبَرْتَنَا بِهَا فَإِنَّهُ لَيْسَ مِنْ نَبِيٍّ إِلَّا لَهُ مَلَكٌ يَأْتِيهِ بِالْخَبَرِ فَأَخْبِرْنَا مَنْ صَاحِبكَ قَالَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالُوا ‏ ‏جِبْرِيلُ ‏ ‏ذَاكَ الَّذِي يَنْزِلُ بِالْحَرْبِ وَالْقِتَالِ وَالْعَذَابِ عَدُوُّنَا لَوْ قُلْتَ ‏ ‏مِيكَائِيلَ ‏ ‏الَّذِي يَنْزِلُ بِالرَّحْمَةِ وَالنَّبَاتِ وَالْقَطْرِ لَكَانَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏مَنْ كَانَ عَدُوًّا ‏ ‏لِجِبْرِيلَ ‏ } ‏إِلَى آخِرِ ‏ ‏الْآيَةَ ‏","","",""],[2354,2354,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏حُسَيْنِ بْنِ وَاقِدٍ ‏ ‏عَنْ ‏ ‏عِلْبَاءَ بْنِ أَحْمَرَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ ‏ ‏فَحَضَرَ النَّحْرُ فَذَبَحْنَا الْبَقَرَةَ عَنْ سَبْعَةٍ وَالْبَعِيرَ عَنْ عَشَرَةٍ ‏","","",""],[2355,2355,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَحْيَى ‏ ‏وَالطَّالَقَانِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي يَلْتَفِتُ يَمِينًا وَشِمَالًا وَلَا ‏ ‏يَلْوِي ‏ ‏عُنُقَهُ خَلْفَ ظَهْرِهِ ‏ ‏قَالَ ‏ ‏الطَّالَقَانِيُّ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْرٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[2356,2356,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَصْحَابِ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْحَظُ ‏ ‏فِي صَلَاتِهِ مِنْ غَيْرِ أَنْ يَلْوِيَ عُنُقَهُ ‏","","",""],[2357,2357,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَأَى مِنْ أَمِيرِهِ شَيْئًا يَكْرَهُهُ فَلْيَصْبِرْ فَإِنَّهُ مَنْ خَالَفَ الْجَمَاعَةَ شِبْرًا فَمَاتَ فَمِيتَتُهُ جَاهِلِيَّةٌ ‏","","",""],[2358,2358,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ مُسْلِمٍ الْعَبْدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْمُتَوَكِّلِ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَ ‏ ‏أَنَّهُ بَاتَ عِنْدَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَقَامَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ فَخَرَجَ فَنَظَرَ فِي السَّمَاءِ ثُمَّ تَلَا هَذِهِ الْآيَةَ الَّتِي فِي ‏ ‏آلِ ‏ ‏عِمْرَانَ ‏ { ‏إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ ‏ ‏حَتَّى بَلَغَ ‏ ‏سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ‏} ‏ثُمَّ رَجَعَ إِلَى الْبَيْتِ فَتَسَوَّكَ وَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى ثُمَّ اضْطَجَعَ ثُمَّ رَجَعَ أَيْضًا فَنَظَرَ فِي السَّمَاءِ ثُمَّ تَلَا هَذِهِ الْآيَةَ ثُمَّ رَجَعَ فَتَسَوَّكَ وَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى ثُمَّ اضْطَجَعَ ثُمَّ رَجَعَ أَيْضًا فَنَظَرَ فِي السَّمَاءِ ثُمَّ تَلَا هَذِهِ الْآيَةَ ثُمَّ رَجَعَ فَتَسَوَّكَ وَتَوَضَّأَ ثُمَّ قَامَ فَصَلَّى ‏","","",""],[2359,2359,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ عَبَّادٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏شَكَّ ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏مَنْصُورٌ ‏ ‏وَحَدَّثَنِي ‏ ‏عَوْنٌ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏بِهَذَا ‏","","",""],[2360,2360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرِيدَ عَلَى ‏ ‏ابْنَةِ حَمْزَةَ ‏ ‏أَنْ يَتَزَوَّجَهَا فَقَالَ إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ‏ ‏وَإِنَّهُ يَحْرُمُ مِنْ الرَّضَاعَةِ مَا يَحْرُمُ مِنْ النَّسَبِ ‏","","",""],[2361,2361,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏قَالَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏ابْنَةِ حَمْزَةَ ‏ ‏وَذَكَرَ مِنْ جَمَالِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ابْنَةُ أَخِي مِنْ الرَّضَاعَةِ ثُمَّ قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا عَلِمْتَ أَنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ مِنْ الرَّضَاعَةِ مَا حَرَّمَ مِنْ النَّسَبِ ‏","","",""],[2362,2362,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ لَا يَرَى ‏ ‏بَأْسًا ‏ ‏أَنْ يَتَزَوَّجَ الرَّجُلُ وَهُوَ مُحْرِمٌ وَيَقُولُ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزَوَّجَ ‏ ‏مَيْمُونَةَ بِنْتَ الْحَارِثِ ‏ ‏بِمَاءٍ يُقَالُ لَهُ ‏ ‏سَرِفُ ‏ ‏وَهُوَ مُحْرِمٌ فَلَمَّا قَضَى نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّتَهُ أَقْبَلَ حَتَّى إِذَا كَانَ بِذَلِكَ الْمَاءِ ‏ ‏أَعْرَسَ ‏ ‏بِهَا ‏","","",""],[2363,2363,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى الْقَتَّاتِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَجُلٍ وَفَخِذُهُ خَارِجَةٌ فَقَالَ غَطِّ فَخِذَكَ فَإِنَّ ‏ ‏فَخِذَ الرَّجُلِ مِنْ عَوْرَتِهِ ‏","","",""],[2364,2364,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَابِقٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ أَيُّ الْقِرَاءَتَيْنِ كَانَتْ أَخِيرًا قِرَاءَةُ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَوْ قِرَاءَةُ ‏ ‏زَيْدٍ ‏ ‏قَالَ قُلْنَا قِرَاءَةُ ‏ ‏زَيْدٍ ‏ ‏قَالَ ‏ ‏لَا إِلَّا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْرِضُ الْقُرْآنَ عَلَى ‏ ‏جَبْرَائِيلَ ‏ ‏كُلَّ عَامٍ مَرَّةً فَلَمَّا كَانَ فِي الْعَامِ الَّذِي قُبِضَ فِيهِ عَرَضَهُ عَلَيْهِ مَرَّتَيْنِ وَكَانَتْ آخِرَ الْقِرَاءَةِ قِرَاءَةُ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[2365,2365,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي قَوْلِهِ ‏ { ‏الم غُلِبَتْ ‏ ‏الرُّومُ ‏ } ‏قَالَ غُلِبَتْ وَغَلَبَتْ قَالَ كَانَ الْمُشْرِكُونَ يُحِبُّونَ أَنْ تَظْهَرَ ‏ ‏فَارِسُ ‏ ‏عَلَى ‏ ‏الرُّومِ ‏ ‏لِأَنَّهُمْ أَهْلُ أَوْثَانٍ وَكَانَ الْمُسْلِمُونَ يُحِبُّونَ أَنْ تَظْهَرَ ‏ ‏الرُّومُ ‏ ‏عَلَى ‏ ‏فَارِسَ ‏ ‏لِأَنَّهُمْ أَهْلُ كِتَابٍ فَذَكَرُوهُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏فَذَكَرَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهُمْ سَيَغْلِبُونَ قَالَ فَذَكَرَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏لَهُمْ فَقَالُوا اجْعَلْ بَيْنَنَا وَبَيْنَكَ أَجَلًا فَإِنْ ظَهَرْنَا كَانَ لَنَا كَذَا وَكَذَا وَإِنْ ظَهَرْتُمْ كَانَ لَكُمْ كَذَا وَكَذَا فَجَعَلَ أَجَلًا خَمْسَ سِنِينَ فَلَمْ يَظْهَرُوا فَذَكَرَ ذَلِكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا جَعَلْتَهَا إِلَى دُونَ ‏ ‏قَالَ أُرَاهُ قَالَ الْعَشْرِ ‏ ‏قَالَ قَالَ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏الْبِضْعُ مَا دُونَ الْعَشْرِ ‏ ‏ثُمَّ ظَهَرَتْ ‏ ‏الرُّومُ ‏ ‏بَعْدُ قَالَ فَذَلِكَ قَوْلُهُ ‏ { ‏الم غُلِبَتْ ‏ ‏الرُّومُ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَيَوْمَئِذٍ يَفْرَحُ الْمُؤْمِنُونَ ‏} ‏قَالَ يَفْرَحُونَ ‏ { ‏بِنَصْرِ اللَّهِ ‏}","","",""],[2366,2366,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ خُثَيْمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏ذَكْوَانُ ‏ ‏حَاجِبُ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ جَاءَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏يَسْتَأْذِنُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَجِئْتُ وَعِنْدَ رَأْسِهَا ابْنُ أَخِيهَا ‏ ‏عَبْدُ اللَّهِ بِنُ عَبْدِ الرَّحْمَنِ ‏ ‏فَقُلْتُ هَذَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَسْتَأْذِنُ فَأَكَبَّ عَلَيْهَا ابْنُ أَخِيهَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَالَ هَذَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏يَسْتَأْذِنُ وَهِيَ تَمُوتُ فَقَالَتْ دَعْنِي مِنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَقَالَ يَا أُمَّتَاهُ إِنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏مِنْ صَالِحِي بَنِيكِ لِيُسَلِّمْ عَلَيْكِ وَيُوَدِّعْكِ فَقَالَتْ ائْذَنْ لَهُ إِنْ شِئْتَ قَالَ فَأَدْخَلْتُهُ فَلَمَّا جَلَسَ قَالَ أَبْشِرِي فَقَالَتْ أَيْضًا فَقَالَ ‏ ‏مَا بَيْنَكِ وَبَيْنَ أَنْ تَلْقَيْ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْأَحِبَّةَ إِلَّا أَنْ تَخْرُجَ الرُّوحُ مِنْ الْجَسَدِ كُنْتِ أَحَبَّ نِسَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ إِلَّا طَيِّبًا وَسَقَطَتْ قِلَادَتُكِ لَيْلَةَ الْأَبْوَاءِ فَأَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى يُصْبِحَ فِي الْمَنْزِلِ وَأَصْبَحَ النَّاسُ لَيْسَ مَعَهُمْ مَاءٌ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَتَيَمَّمُوا صَعِيدًا طَيِّبًا ‏} ‏فَكَانَ ذَلِكَ فِي سَبَبِكِ وَمَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ لِهَذِهِ الْأُمَّةِ مِنْ الرُّخْصَةِ وَأَنْزَلَ اللَّهُ بَرَاءَتَكِ مِنْ فَوْقِ سَبْعِ سَمَوَاتٍ جَاءَ بِهِ ‏ ‏الرُّوحُ الْأَمِينُ ‏ ‏فَأَصْبَحَ لَيْسَ لِلَّهِ مَسْجِدٌ مِنْ مَسَاجِدِ اللَّهِ يُذْكَرُ اللَّهُ فِيهِ إِلَّا يُتْلَى فِيهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ فَقَالَتْ دَعْنِي مِنْكَ يَا ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ لَوَدِدْتُ أَنِّي كُنْتُ نَسْيًا مَنْسِيًّا ‏","","",""],[2367,2367,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لَهَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏إِنَّمَا ‏ ‏سُمِّيتِ أُمَّ الْمُؤْمِنِينَ لِتَسْعَدِي وَإِنَّهُ لَاسْمُكِ قَبْلَ أَنْ تُولَدِي ‏","","",""],[2368,2368,"","","‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَالَ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[2369,2369,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَأَنْ يُخْلَطَ الْبَلَحُ وَالزَّهْوُ ‏","","",""],[2370,2370,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏كَانَ الْفَتْحُ فِي ثَلَاثَ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ ‏","","",""],[2371,2371,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَذَكَرُوا ‏ ‏الدَّجَّالَ ‏ ‏فَقَالُوا إِنَّهُ ‏ ‏مَكْتُوبٌ ‏ ‏بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏ ‏قَالَ ‏ ‏مَا تَقُولُونَ قَالَ يَقُولُونَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏ ‏قَالَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَمْ أَسْمَعْهُ قَالَ ذَلِكَ وَلَكِنْ قَالَ ‏ ‏أَمَّا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَانْظُرُوا إِلَى صَاحِبِكُمْ وَأَمَّا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَرَجُلٌ آدَمُ ‏ ‏جَعْدٌ ‏ ‏عَلَى جَمَلٍ أَحْمَرَ ‏ ‏مَخْطُومٍ ‏ ‏بِخُلْبَةٍ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ إِذَا انْحَدَرَ فِي ‏ ‏الْوَادِي ‏ ‏يُلَبِّي ‏","","",""],[2372,2372,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏ذَكَرُوهُ ‏ ‏يَعْنِي ‏ ‏الدَّجَّالَ ‏ ‏فَقَالَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَمْ أَسْمَعْهُ يَقُولُ ذَاكَ وَلَكِنْ قَالَ ‏ ‏أَمَّا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَانْظُرُوا إِلَى صَاحِبِكُمْ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَعْنِي نَفْسَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَّا ‏ ‏مُوسَى ‏ ‏فَرَجُلٌ ‏ ‏آدَمُ ‏ ‏جَعْدٌ ‏ ‏طُوَالٌ عَلَى جَمَلٍ أَحْمَرَ ‏ ‏مَخْطُومٍ ‏ ‏بِخُلْبَةٍ ‏ ‏كَأَنِّي أَنْظُرُ إِلَيْهِ وَقَدْ انْحَدَرَ فِي ‏ ‏الْوَادِي ‏ ‏يُلَبِّي ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏الْخُلْبَةُ اللِّيفُ ‏","","",""],[2373,2373,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏أَظُنُّهُ قَدْ رَفَعَهُ ‏ ‏قَالَ ‏ ‏أَمَرَ مُنَادِيًا فَنَادَى فِي يَوْمٍ مَطِيرٍ أَنْ صَلُّوا فِي رِحَالِكُمْ ‏","","",""],[2374,2374,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ نَافِعٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ ‏ ‏مَاتَتْ شَاةٌ فِي بَعْضِ بُيُوتِ نِسَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَّا انْتَفَعْتُمْ بِمَسْكِهَا ‏","","",""],[2375,2375,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي بُكَيْرٍ هُوَ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ نَافِعٍ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ مِينَاسٍ الْعَدَنِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ السُّجُودَ بَعْدَ الرَّكْعَةِ يَقُولُ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ ‏","","",""],[2376,2376,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏وُلِدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ وَاسْتُنْبِئَ يَوْمَ ‏ ‏الِاثْنَيْنِ وَتُوُفِّيَ يَوْمَ ‏ ‏الِاثْنَيْنِ وَخَرَجَ مُهَاجِرًا مِنْ ‏ ‏مَكَّةَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ وَقَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ وَرَفَعَ الْحَجَرَ الْأَسْوَدَ يَوْمَ ‏ ‏الِاثْنَيْنِ ‏","","",""],[2377,2377,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَاتٍ ‏ ‏وَاقِفًا وَقَدْ ‏ ‏أَرْدَفَ ‏ ‏الْفَضْلَ ‏ ‏فَجَاءَ أَعْرَابِيٌّ فَوَقَفَ قَرِيبًا وَأَمَةٌ خَلْفَهُ فَجَعَلَ ‏ ‏الْفَضْلُ ‏ ‏يَنْظُرُ إِلَيْهَا فَفَطِنَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ يَصْرِفُ وَجْهَهُ قَالَ ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏لَيْسَ الْبِرُّ ‏ ‏بِإِيجَافِ ‏ ‏الْخَيْلِ وَلَا الْإِبِلِ فَعَلَيْكُمْ بِالسَّكِينَةِ قَالَ ثُمَّ ‏ ‏أَفَاضَ ‏ ‏قَالَ فَمَا رَأَيْتُهَا رَافِعَةً يَدَهَا ‏ ‏عَادِيَةً ‏ ‏حَتَّى أَتَى ‏ ‏جَمْعًا ‏ ‏قَالَ فَلَمَّا وَقَفَ ‏ ‏بِجَمْعٍ ‏ ‏أَرْدَفَ ‏ ‏أُسَامَةَ ‏ ‏ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ إِنَّ الْبِرَّ لَيْسَ ‏ ‏بِإِيجَافِ ‏ ‏الْخَيْلِ وَالْإِبِلِ فَعَلَيْكُمْ بِالسَّكِينَةِ قَالَ ثُمَّ ‏ ‏أَفَاضَ ‏ ‏فَمَا رَأَيْتُهَا رَافِعَةً يَدَهَا ‏ ‏عَادِيَةً ‏ ‏حَتَّى أَتَتْ ‏ ‏مِنًى ‏ ‏فَأَتَانَا سَوَادَ ضَعْفَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏عَلَى حُمُرَاتٍ لَهُمْ فَجَعَلَ يَضْرِبُ أَفْخَاذَنَا وَيَقُولُ يَا بَنِيَّ ‏ ‏أَفِيضُوا ‏ ‏وَلَا تَرْمُوا ‏ ‏الْجَمْرَةَ ‏ ‏حَتَّى تَطْلُعَ الشَّمْسُ ‏","","",""],[2378,2378,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏بُكَيْرًا ‏ ‏حَدَّثَهُ عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ دَخَلَ الْبَيْتَ وَجَدَ فِيهِ صُورَةَ ‏ ‏إِبْرَاهِيمَ ‏ ‏وَصُورَةَ ‏ ‏مَرْيَمَ ‏ ‏فَقَالَ ‏ ‏أَمَّا هُمْ فَقَدْ سَمِعُوا أَنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ صُورَةٌ هَذَا ‏ ‏إِبْرَاهِيمُ ‏ ‏مُصَوَّرًا فَمَا بَالُهُ يَسْتَقْسِمُ ‏","","",""],[2379,2379,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو صَخْرٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ مَاتَ ابْنٌ لَهُ ‏ ‏بِقُدَيْدٍ ‏ ‏أَوْ ‏ ‏بِعُسْفَانَ ‏ ‏فَقَالَ يَا ‏ ‏كُرَيْبُ ‏ ‏انْظُرْ مَا اجْتَمَعَ لَهُ مِنْ النَّاسِ قَالَ فَخَرَجْتُ فَإِذَا نَاسٌ قَدْ اجْتَمَعُوا لَهُ فَأَخْبَرْتُهُ قَالَ يَقُولُ هُمْ أَرْبَعُونَ قَالَ نَعَمْ قَالَ أَخْرِجُوهُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يَمُوتُ فَيَقُومُ عَلَى جِنَازَتِهِ أَرْبَعُونَ رَجُلًا لَا يُشْرِكُونَ بِاللَّهِ شَيْئًا ‏ ‏إِلَّا شَفَّعَهُمْ اللَّهُ فِيهِ ‏","","",""],[2380,2380,"","","‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ يَعْنِي الْخَطَّابِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَجُلًا خَرَجَ فَتَبِعَهُ رَجُلَانِ وَرَجُلٌ ‏ ‏يَتْلُوهُمَا يَقُولُ ارْجِعَا قَالَ فَرَجَعَا قَالَ فَقَالَ لَهُ إِنَّ هَذَيْنِ شَيْطَانَانِ وَإِنِّي لَمْ أَزَلْ بِهِمَا حَتَّى رَدَدْتُهُمَا فَإِذَا أَتَيْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَقْرِئْهُ السَّلَامَ وَأَعْلِمْهُ أَنَّا فِي جَمْعِ صَدَقَاتِنَا وَلَوْ كَانَتْ تَصْلُحُ لَهُ لَأَرْسَلْنَا بِهَا إِلَيْهِ قَالَ ‏ ‏فَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ ‏ ‏عَنْ الْخَلْوَةِ ‏","","",""],[2381,2381,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏قَالَ ‏ ‏مَا أَدْرَكْنَا أَحَدًا أَقْوَمَ بِقَوْلِ ‏ ‏الشِّيعَةِ ‏ ‏مِنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏","","",""],[2382,2382,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ يَعْنِي الْخَطَّابِيَّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ حَبْتَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَنُ الْكَلْبِ خَبِيثٌ قَالَ فَإِذَا جَاءَكَ يَطْلُبُ ثَمَنَ الْكَلْبِ فَامْلَأْ كَفَّيْهِ تُرَابًا ‏","","",""],[2383,2383,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏بَلْهُجَيْمٍ ‏ ‏يَا ‏ ‏أَبَا الْعَبَّاسِ ‏ ‏مَا هَذِهِ الْفُتْيَا الَّتِي ‏ ‏تَفَشَّغَتْ ‏ ‏بِالنَّاسِ أَنَّ ‏ ‏مَنْ طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏فَقَدْ ‏ ‏حَلَّ ‏ ‏فَقَالَ سُنَّةُ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنْ ‏ ‏رَغِمْتُمْ ‏","","",""],[2384,2384,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرٌ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏حَضَرَتْ عِصَابَةٌ مِنْ ‏ ‏الْيَهُودِ ‏ ‏نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَقَالُوا يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏حَدِّثْنَا عَنْ ‏ ‏خِلَالٍ ‏ ‏نَسْأَلُكَ عَنْهُنَّ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ قَالَ سَلُونِي عَمَّا شِئْتُمْ وَلَكِنْ اجْعَلُوا لِي ‏ ‏ذِمَّةَ ‏ ‏اللَّهِ وَمَا أَخَذَ ‏ ‏يَعْقُوبُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَلَى بَنِيهِ لَئِنْ حَدَّثْتُكُمْ شَيْئًا فَعَرَفْتُمُوهُ ‏ ‏لَتُتَابِعُنِّي عَلَى الْإِسْلَامِ قَالُوا فَذَلِكَ لَكَ قَالَ فَسَلُونِي عَمَّا شِئْتُمْ قَالُوا أَخْبِرْنَا عَنْ أَرْبَعِ ‏ ‏خِلَالٍ ‏ ‏نَسْأَلُكَ عَنْهُنَّ أَخْبِرْنَا أَيُّ الطَّعَامِ حَرَّمَ ‏ ‏إِسْرَائِيلُ ‏ ‏عَلَى نَفْسِهِ مِنْ قَبْلِ أَنْ تُنَزَّلَ التَّوْرَاةُ وَأَخْبِرْنَا كَيْفَ مَاءُ الْمَرْأَةِ وَمَاءُ الرَّجُلِ كَيْفَ يَكُونُ الذَّكَرُ مِنْهُ وَأَخْبِرْنَا كَيْفَ هَذَا النَّبِيُّ الْأُمِّيُّ فِي النَّوْمِ وَمَنْ ‏ ‏وَلِيُّهُ ‏ ‏مِنْ الْمَلَائِكَةِ قَالَ فَعَلَيْكُمْ عَهْدُ اللَّهِ وَمِيثَاقُهُ لَئِنْ أَنَا أَخْبَرْتُكُمْ ‏ ‏لَتُتَابِعُنِّي قَالَ فَأَعْطَوْهُ مَا شَاءَ مِنْ عَهْدٍ وَمِيثَاقٍ قَالَ فَأَنْشُدُكُمْ بِالَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَعْلَمُونَ أَنَّ ‏ ‏إِسْرَائِيلَ يَعْقُوبَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَرِضَ مَرَضًا شَدِيدًا وَطَالَ سَقَمُهُ فَنَذَرَ لِلَّهِ ‏ ‏نَذْرًا ‏ ‏لَئِنْ شَفَاهُ اللَّهُ تَعَالَى مِنْ سَقَمِهِ لَيُحَرِّمَنَّ أَحَبَّ الشَّرَابِ إِلَيْهِ وَأَحَبَّ الطَّعَامِ إِلَيْهِ وَكَانَ أَحَبَّ الطَّعَامِ إِلَيْهِ ‏ ‏لُحْمَانُ الْإِبِلِ وَأَحَبَّ الشَّرَابِ إِلَيْهِ أَلْبَانُهَا قَالُوا اللَّهُمَّ نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ عَلَيْهِمْ ‏ ‏فَأَنْشُدُكُمْ ‏ ‏بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى ‏ ‏مُوسَى ‏ ‏هَلْ تَعْلَمُونَ أَنَّ ‏ ‏مَاءَ ‏ ‏الرَّجُلِ أَبْيَضُ غَلِيظٌ وَأَنَّ ‏ ‏مَاءَ ‏ ‏الْمَرْأَةِ أَصْفَرُ رَقِيقٌ فَأَيُّهُمَا عَلَا كَانَ لَهُ الْوَلَدُ وَالشَّبَهُ بِإِذْنِ اللَّهِ إِنْ عَلَا ‏ ‏مَاءُ ‏ ‏الرَّجُلِ عَلَى ‏ ‏مَاءِ ‏ ‏الْمَرْأَةِ كَانَ ذَكَرًا بِإِذْنِ اللَّهِ وَإِنْ عَلَا ‏ ‏مَاءُ ‏ ‏الْمَرْأَةِ عَلَى ‏ ‏مَاءِ ‏ ‏الرَّجُلِ كَانَ أُنْثَى بِإِذْنِ اللَّهِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ عَلَيْهِمْ ‏ ‏فَأَنْشُدُكُمْ ‏ ‏بِالَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى ‏ ‏مُوسَى ‏ ‏هَلْ تَعْلَمُونَ أَنَّ هَذَا النَّبِيَّ الْأُمِّيَّ تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ قَالُوا اللَّهُمَّ نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ قَالُوا وَأَنْتَ الْآنَ فَحَدِّثْنَا مَنْ وَلِيُّكَ مِنْ الْمَلَائِكَةِ فَعِنْدَهَا نُجَامِعُكَ أَوْ نُفَارِقُكَ قَالَ فَإِنَّ ‏ ‏وَلِيِّيَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَلَمْ يَبْعَثْ اللَّهُ نَبِيًّا قَطُّ إِلَّا وَهُوَ وَلِيُّهُ قَالُوا فَعِنْدَهَا نُفَارِقُكَ لَوْ كَانَ وَلِيُّكَ سِوَاهُ مِنْ الْمَلَائِكَةِ لَتَابَعْنَاكَ وَصَدَّقْنَاكَ قَالَ فَمَا يَمْنَعُكُمْ مِنْ أَنْ تُصَدِّقُوهُ قَالُوا إِنَّهُ عَدُوُّنَا قَالَ فَعِنْدَ ذَلِكَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏قُلْ مَنْ كَانَ عَدُوًّا ‏ ‏لِجِبْرِيلَ ‏ ‏فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ بِإِذْنِ اللَّهِ ‏ ‏إِلَى قَوْلِهِ عَزَّ وَجَلَّ ‏ ‏كِتَابَ اللَّهِ وَرَاءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ ‏} ‏فَعِنْدَ ذَلِكَ ‏ { ‏بَاءُوا بِغَضَبٍ عَلَى غَضَبٍ ‏} ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرٌ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏بِنَحْوِهِ ‏","","",""],[2385,2385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ عَلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏وَهُوَ يَأْكُلُ رُمَّانًا ‏ ‏بِعَرَفَةَ ‏ ‏وَحَدَّثَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏بَعَثَتْ إِلَيْهِ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏بِلَبَنٍ فَشَرِبَ ‏","","",""],[2386,2386,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏بِعَرَفَةَ ‏ ‏قَالَ بَعَثَتْ إِلَيْهِ ‏ ‏أُمُّ الْفَضْلِ ‏ ‏بِلَبَنٍ فَشَرِبَهُ ‏","","",""],[2387,2387,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ سَلَمَةَ ‏ ‏قَالَ ‏ ‏حَجَجْتُ أَنَا ‏ ‏وَسِنَانُ بْنُ سَلَمَةَ ‏ ‏وَمَعَ ‏ ‏سِنَانٍ ‏ ‏بَدَنَةٌ ‏ ‏فَأَزْحَفَتْ عَلَيْهِ فَعَيَّ بِشَأْنِهَا فَقُلْتُ لَئِنْ قَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏لَأَسْتَبْحِثَنَّ عَنْ هَذَا قَالَ فَلَمَّا قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏قُلْتُ انْطَلِقْ بِنَا إِلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَدَخَلْنَا عَلَيْهِ وَعِنْدَهُ جَارِيَةٌ وَكَانَ لِي حَاجَتَانِ وَلِصَاحِبِي حَاجَةٌ فَقَالَ أَلَا ‏ ‏أُخْلِيكَ قُلْتُ لَا فَقُلْتُ كَانَتْ مَعِي ‏ ‏بَدَنَةٌ ‏ ‏فَأَزْحَفَتْ عَلَيْنَا فَقُلْتُ لَئِنْ قَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏لَأَسْتَبْحِثَنَّ عَنْ هَذَا فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبُدْنِ ‏ ‏مَعَ فُلَانٍ وَأَمَرَهُ فِيهَا بِأَمْرِهِ فَلَمَّا ‏ ‏قَفَّا ‏ ‏رَجَعَ فَقَالَ يَا رَسُولَ اللَّهِ مَا أَصْنَعُ بِمَا ‏ ‏أَزْحَفَ ‏ ‏عَلَيَّ مِنْهَا قَالَ انْحَرْهَا وَاصْبُغْ نَعْلَهَا فِي دَمِهَا وَاضْرِبْهُ عَلَى ‏ ‏صَفْحَتِهَا ‏ ‏وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ رُفْقَتِكَ قَالَ فَقُلْتُ لَهُ أَكُونُ فِي هَذِهِ الْمَغَازِي فَأُغْنَمُ فَأُعْتِقُ عَنْ أُمِّي أَفَيُجْزِئُ عَنْهَا أَنْ أُعْتِقَ فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَمَرَتْ ‏ ‏امْرَأَةُ سَلْمَانَ بْنِ عَبْدِ اللَّهِ الْجُهَنِيَّ ‏ ‏أَنْ يَسْأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أُمِّهَا تُوُفِّيَتْ وَلَمْ تَحْجُجْ أَيُجْزِئُ عَنْهَا أَنْ تَحُجَّ عَنْهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ لَوْ كَانَ عَلَى أُمِّهَا دَيْنٌ فَقَضَتْهُ عَنْهَا أَكَانَ يُجْزِئُ عَنْ أُمِّهَا قَالَ نَعَمْ قَالَ فَلْتَحْجُجْ عَنْ أُمِّهَا وَسَأَلَهُ عَنْ مَاءِ الْبَحْرِ فَقَالَ مَاءُ الْبَحْرِ طَهُورٌ ‏","","",""],[2388,2388,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏الْجَعْدُ أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ الْعُطَارِدِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا رَوَى عَنْ رَبِّهِ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَبَّكُمْ تَبَارَكَ وَتَعَالَى رَحِيمٌ مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشَرَةً إِلَى سَبْعِ مِائَةٍ إِلَى أَضْعَافٍ كَثِيرَةٍ وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ وَاحِدَةً أَوْ ‏ ‏يَمْحُوهَا اللَّهُ وَلَا يَهْلِكُ عَلَى اللَّهِ تَعَالَى إِلَّا هَالِكٌ ‏","","",""],[2389,2389,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ فِي تَاسِعَةٍ تَبْقَى أَوْ سَابِعَةٍ تَبْقَى أَوْ خَامِسَةٍ تَبْقَى ‏","","",""],[2390,2390,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجَدَ فِي ‏ ‏ص ‏","","",""],[2391,2391,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ وَعْلَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّا نَغْزُو أَهْلَ ‏ ‏الْمَغْرِبِ ‏ ‏وَأَكْثَرُ ‏ ‏أَسْقِيَتِهِمْ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَعَامَّةُ أَسْقِيَتِهِمْ ‏ ‏الْمَيْتَةُ ‏ ‏فَقَالَ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏دِبَاغُهَا ‏ ‏طُهُورُهَا ‏","","",""],[2392,2392,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَكَّةَ ‏ ‏خَمْسَ عَشْرَةَ سَنَةً سَبْعَ سِنِينَ يَرَى الضَّوْءَ وَيَسْمَعُ الصَّوْتَ وَثَمَانِي سِنِينَ يُوحَى إِلَيْهِ وَأَقَامَ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَشْرَ سِنِينَ ‏","","",""],[2393,2393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْتَهَسَ مِنْ كَتِفٍ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ ‏","","",""],[2394,2394,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَمَّارٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَمْ يَنْسُبْهُ ‏ ‏عَفَّانُ ‏ ‏أَكْثَرَ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَإِيَّايَ رَأَى فَإِنَّ الشَّيْطَانَ لَا يَتَخَيَّلُ بِي ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً لَا يَتَخَيَّلُنِي ‏","","",""],[2395,2395,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ زَيْدٍ ‏ ‏يُخْبِرُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ ‏ ‏بِعَرَفَاتٍ ‏ ‏مَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ وَمَنْ لَمْ يَجِدْ ‏ ‏إِزَارًا ‏ ‏فَلْيَلْبَسْ سَرَاوِيلَ ‏","","",""],[2396,2396,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَاوُسًا ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ ‏ ‏أَعْظُمٍ ‏ ‏وَلَا ‏ ‏أَكُفَّ ‏ ‏شَعَرًا وَلَا ثَوْبًا ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أُخْرَى أُمِرَ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْجُدَ عَلَى سَبْعَةِ ‏ ‏أَعْظُمٍ ‏ ‏وَلَا ‏ ‏يَكُفَّ ‏ ‏شَعَرًا وَلَا ثَوْبًا ‏","","",""],[2397,2397,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا حَسَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏ثُمَّ أُتِيَ بِبَدَنَتِهِ ‏ ‏فَأَشْعَرَ ‏ ‏صَفْحَةَ ‏ ‏سَنَامِهَا الْأَيْمَنِ ثُمَّ سَلَتَ الدَّمَ عَنْهَا ثُمَّ ‏ ‏قَلَّدَهَا ‏ ‏نَعْلَيْنِ ثُمَّ أُتِيَ ‏ ‏بِرَاحِلَتِهِ ‏ ‏فَلَمَّا قَعَدَ عَلَيْهَا ‏ ‏وَاسْتَوَتْ ‏ ‏بِهِ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ ‏","","",""],[2398,2398,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ ‏","","",""],[2399,2399,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أُهْدِيَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجُزُ ‏ ‏حِمَارٍ ‏ ‏أَوْ قَالَ رِجْلُ حِمَارٍ ‏ ‏وَهُوَ مُحْرِمٌ فَرَدَّهُ ‏","","",""],[2400,2400,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُوسُفُ بْنُ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏حَزَبَهُ ‏ ‏أَمْرٌ قَالَ لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيمُ الْحَلِيمُ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْكَرِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الْأَرْضِ رَبُّ الْعَرْشِ الْكَرِيمِ ‏","","",""]];
